const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let all=[],selected=null,view='dashboard',catalog=[],config=null,dirty=false,busy=false,lineFilter='',shopFilter=null,projectFilter='',projectSearch='',summarySort={key:'category',direction:1},mobileOpen=false,configBaseline=null;
const openRoomGroups=new Set(),stageInvoiceCache=new Map(),stageInvoiceErrors=new Set(),projectEarningsCache=new Map();
let completionReturnId=null,settlementReturnId=null;
let stockPanel=null,stockMountGeneration=0;
function closeStock(){stockMountGeneration++;stockPanel?.unmount();}
async function mountStockPanel(){
 const host=$('#robisie-stock-panel'),generation=++stockMountGeneration;
 try{const module=await import('../../bill/ksef.js?v=1.0.38');if(generation!==stockMountGeneration||view!=='stock'||$('#robisie-stock-panel')!==host)return;stockPanel=module;module.mountStock(host,API.ksefCall,API.stockIntegration(all,row=>{all=all.map(r=>r.id===row.id?{...row,payload:C.captureCatalog(config.payload,row.payload)}:r);}));}
 catch(error){if(generation===stockMountGeneration&&view==='stock')host.textContent='Nie udało się wczytać towarów: '+error.message;}
}
let earningsGeneration=0,earningsModule=null,earningsRows=null,earningsError='',earningsYear=C.today().slice(0,4),earningsMonth='';
function resetEarningsSummary(){earningsGeneration++;earningsRows=null;earningsError='';}
function earningsSummaryView(){return earningsRows&&earningsModule?earningsModule.markup(earningsRows,{year:earningsYear,month:earningsMonth}):`<section class="card"><p role="status">${esc(earningsError||'Wczytywanie podsumowania zarobków…')}</p>${earningsError?btn('earnings-refresh','Spróbuj ponownie'):''}</section>`;}
async function loadEarningsSummary(){
 const generation=++earningsGeneration,owner=API.getSession?.()?.user?.id;earningsRows=null;earningsError='';render();
 const current=()=>generation===earningsGeneration&&view==='earnings-summary'&&API.getSession?.()?.user?.id===owner&&!!owner;
 try{const [module,data]=await Promise.all([import('./earnings-summary.js?v=1.0.81'),API.earningsSummaryData()]);if(!current())return;earningsModule=module;earningsRows=module.records(data.projects,data.earnings);render();}
 catch(error){if(current()){earningsError='Nie udało się wczytać podsumowania: '+error.message;render();}}
}
let stageInvoiceLoading=null,purchaseDialogLoading=false;
function invoiceHref(row){return row.externalKsef&&!row.sourceBillId?'/bill/?ksef='+encodeURIComponent(row.ksef_number)+'&month='+encodeURIComponent(row.payload.issueDate.slice(0,7))+'&kind='+encodeURIComponent(row.originKind||'sales'):'/bill/?invoice='+encodeURIComponent(row.sourceBillId||row.id);}
function stageInvoiceCell(stage){const records=stageInvoiceCache.get(selected.id)||[],assigned=new Set((p().invoiceSettlements||[]).filter(r=>r.allocations.some(a=>a.kind==='stage'&&a.id===stage.id&&a.amount>0)).map(r=>r.id)),linked=records.filter(row=>row.payload?.source?.stageId===stage.id||assigned.has(row.id));if(linked.length)return linked.map(invoice=>`<a class="button" href="${invoiceHref(invoice)}" target="_blank" rel="noopener">${esc(invoice.number||'Kontynuuj szkic')}</a>`).join(' ');if(stage.invoice)return esc(stage.invoice);return `<a class="button" data-action="stage-invoice" href="/bill/?new=1&amp;brand=robisie&amp;source=${encodeURIComponent(selected.id)}&amp;stage=${encodeURIComponent(stage.id)}" target="_blank" rel="noopener">Dodaj</a>`;}
async function loadStageInvoices(){const id=selected?.id;if(!id||!API.stageInvoices||stageInvoiceLoading===id)return;stageInvoiceLoading=id;try{const rows=await API.stageInvoices(id);stageInvoiceCache.set(id,rows);stageInvoiceErrors.delete(id);if(API.project&&selected?.id===id&&!dirty&&!writes.pending){const revision=selected.revision,latest=await API.project(id);if(latest&&selected?.id===id&&selected.revision===revision&&!dirty&&!writes.pending&&latest.revision!==revision){selected=structuredClone(latest);all=all.map(r=>r.id===id?structuredClone(latest):r);}}if(selected?.id===id&&['payments','overview'].includes(view)&&!$('#dialog').open)render();}catch{stageInvoiceErrors.add(id);if(selected?.id===id&&view==='overview'&&!$('#dialog').open)render();if(selected?.id===id&&view==='payments')toast('Nie udało się odświeżyć powiązanych faktur. Możesz je sprawdzić w Bill.');}finally{if(stageInvoiceLoading===id)stageInvoiceLoading=null;}}
const writes=new Auto.WriteQueue(updateSaveState),drafts=new Auto.DraftStore(()=>globalThis.localStorage,()=>API.getSession?.()?.user?.id||'administrator');
let projectDirty=false,settingsDirty=false,autoSaveTimer=null,saveError='',modalSubmitting=false;
function updateSaveState(){dirty=projectDirty||settingsDirty;if(config)for(const button of document.querySelectorAll('[data-action="undo-changes"]')){if(button.dataset?.action==='undo-changes'){const scope=undoScope(),available=scope==='settings'?config.payload._undo:p()?._undo;button.disabled=writes.pending>0||(!available&&!dirty);}}const bar=$('#save-state');if(bar)bar.textContent=saveError?'Błąd zapisu — kopia zachowana na urządzeniu':writes.pending?'Zapisywanie…':dirty?'Oczekiwanie na automatyczny zapis':'Dane zapisane w bazie';}
function keepDraft(scope){try{if(scope==='settings'&&config)drafts.put('settings',configBaseline.revision,config.payload);else if(selected)drafts.put('project:'+selected.id,selected.revision,selected.payload);}catch{toast('Brak miejsca na kopię lokalną. Poczekaj na potwierdzenie zapisu w bazie przed zamknięciem aplikacji.');}}
function scheduleSave(){clearTimeout(autoSaveTimer);autoSaveTimer=setTimeout(()=>{if($('#dialog')?.open||modalSubmitting)return;flushChanges({normalize:false}).catch(saveFailed);},700);}
function saveFailed(error){saveError=error.message;updateSaveState();toast('Nie udało się zapisać: '+error.message+'. Zmiany zachowano do ponownego zapisu.');}
function undoScope(){if(!selected)return 'settings';if(view==='catalog'&&config.payload._undo?.savedAt>(p()._undo?.savedAt||''))return 'settings';return 'project';}
function undoButton(){const scope=undoScope(),available=scope==='settings'?config.payload._undo:p()?._undo;return btn('undo-changes','Cofnij zmiany','primary',!available&&!dirty?'disabled':'');}
function recoveryNotice(){const key=selected?'project:'+selected.id:'settings',draft=drafts.read()[key],revision=selected?selected.revision:config.revision;if(!draft||draft.revision===revision)return '';return `<div class="notice error">Na urządzeniu jest niezapisana kopia, a dane w bazie zmieniły się w międzyczasie. ${btn('draft-restore','Przywróć kopię z urządzenia','',`data-key="${esc(key)}"`)} ${btn('draft-discard','Zachowaj dane z bazy','',`data-key="${esc(key)}"`)}</div>`;}
function restoreDraft(key,row){const draft=drafts.read()[key];if(!draft)return false;if(Auto.samePayload(draft.payload,row.payload)){drafts.remove(key);return false;}if(draft.revision!==row.revision)return false;row.payload={...draft.payload,...(row.payload._undo?{_undo:row.payload._undo}:{})};return true;}

const statuses={przygotowanie:'Przygotowanie',oferta:'Oferta',prace:'W realizacji',odbior:'Do odbioru',zakonczona:'Zakończona'};
const defaults=()=>({catalog:structuredClone(catalog),markup:35,company:{name:'ROBISIĘ-FER sp. z o.o.',address:'Rtm. Witolda Pileckiego 18, 43-190 Mikołów',nip:'6351861297',krs:'',representative:'Michał Sobota – prezes zarządu',account:''}});
const p=()=>selected?.payload;
const currentCatalog=()=>C.projectCatalog(config.payload,p());
const currentMarkup=()=>C.catalogMarkup(config.payload,p());
function acceptConfig(row){config=Array.isArray(row)?row[0]:row;configBaseline=structuredClone(config);}
async function persistCatalog(payload){
 const base=Auto.snapshot(configBaseline.payload);
 return writes.run(async()=>{
  const desired=Auto.mergeEdits(config.payload,base,payload),previous=configBaseline.payload;
  if(config.revision>0&&Auto.samePayload(desired,previous)){settingsDirty=false;drafts.remove('settings');return;}
  const changesHistory=JSON.stringify(desired.catalogCorrections||[])!==JSON.stringify(previous.catalogCorrections||[]);
  config.payload=desired;settingsDirty=true;keepDraft('settings');updateSaveState();
  const submitted=structuredClone(desired),result=await API.saveSettings(Auto.withUndo(desired,previous),config.revision,previous),row=Array.isArray(result)?result[0]:result;
  if(Auto.samePayload(config.payload,submitted)){acceptConfig(row);settingsDirty=false;drafts.remove('settings');}
  else{config.revision=row.revision;config.payload=Auto.mergeEdits(row.payload,submitted,config.payload);configBaseline=structuredClone(row);settingsDirty=true;keepDraft('settings');scheduleSave();}
  if(changesHistory)all=await API.projects();
 }).finally(updateSaveState);
}

const title=()=>C.MODULES.find(x=>x[0]===view)?.[1]||({dashboard:'Panel administratora',stock:'Magazyn',catalog:'Cennik',settings:'Dane wykonawcy',trips:'Dojazdy','earnings-summary':'Podsumowanie zarobków'}[view]||'Robisię');
const btn=(action,label,cls='',extra='')=>`<button type="button" data-action="${action}" class="${cls}" ${extra}>${label}</button>`;
const input=(name,label,value='',type='text',extra='')=>`<div class="field"><label for="f-${esc(name)}">${label}</label><input id="f-${esc(name)}" name="${esc(name)}" type="${type==='number'?'text':type}" ${type==='number'?'data-numeric="true" inputmode="text" autocomplete="off" autocapitalize="off" spellcheck="false" title="Możesz wpisać liczbę lub działanie, np. 25+3+7-2"':''} value="${esc(value)}" ${p()?.calculationPrecision==='source'&&type==='number'?extra.replace(/step="[^"]+"/g,'step="any"'):extra}></div>`;
const text=(name,label,value='',extra='')=>`<div class="field"><label for="f-${esc(name)}">${label}</label><textarea id="f-${esc(name)}" name="${esc(name)}" ${extra}>${esc(value)}</textarea></div>`;
const field=(name,label,value,type='text',extra='')=>input(name,label,value,type,`data-field="${name}" ${extra}`);
const metric=(label,value,cls='')=>`<div class="metric ${cls}"><small>${label}</small><strong>${value}</strong></div>`;
const table=(heads,rows)=>`<div class="tablewrap"><table><thead><tr>${heads.map(h=>typeof h==='object'?`<th aria-sort="${h.sort}">${h.html}</th>`:`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${heads.length}" class="empty">Brak pozycji</td></tr>`}</tbody></table></div>`;
function logoMarkup(className='',absolute=false){const path='./assets/robisie-logo.png?v='+C.VERSION,src=absolute?new URL(path,window.location.href).href:path;return `<img class="brand-logo ${className}" src="${esc(src)}" alt="Robisię — fachowa ekipa remontowa" width="719" height="297">`;}
const money=C.money;
const date=v=>v?esc(v):'—';
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000);}
function markDirty(scope=selected?'project':'settings'){if(scope==='settings')settingsDirty=true;else projectDirty=true;saveError='';keepDraft(scope);updateSaveState();scheduleSave();}
function roomName(id){return p()?.rooms.find(r=>r.id===id)?.name||'Cała inwestycja';}
function card(content){return `<section class="card">${content}</section>`;}
function documents(){const s=selected;return [['UMOWA',s.contract_number],['WYMIARY',C.attachment(s,'WYM')],['OFERTA',C.attachment(s,'OFE',C.activeOffer(p())?.version||1)],['KALKULACJA KOŃCOWA',C.attachment(s,'KAL-K')],['ROZLICZENIE',C.attachment(s,'ROZ')],['DZIENNIK',C.attachment(s,'DZR')],['PROTOKÓŁ',C.attachment(s,'PZO')],['MATERIAŁY',C.attachment(s,'ZRM')]];}
async function start(){
 try{catalog=await fetch('./catalog.json').then(r=>{if(!r.ok)throw new Error('Nie można wczytać cennika.');return r.json();});
 if(!API.restoreSession()){loginView();return;}await load();
 }catch(e){failure(e);}
}
function loginView(message=''){resetEarningsSummary();closeStock();stockPanel?.reset();$('#app').innerHTML=`<div class="login card">${logoMarkup()}<p class="muted">Inwestycje remontowe</p><h1>Logowanie administratora</h1>${message?`<div class="notice error">${esc(message)}</div>`:''}<form id="login">${input('email','Adres e-mail','','email','autocomplete="username" required')}${input('password','Hasło','','password','autocomplete="current-password" required')}<button class="primary" type="submit">Zaloguj się</button></form><p class="muted" style="margin-top:22px">Użyj konta administratora CleanFleet.</p><span class="version">Wersja ${C.VERSION}</span></div>`;}
function failure(e){if(e.code==='PGRST205'||e.code==='PGRST202'||/rs_projects|rs_settings|rs_create_project/.test(e.message)){
 $('#app').innerHTML=`<div class="login card">${logoMarkup()}<h1>Aplikacja czeka na uruchomienie bazy</h1><p>Moduły są przygotowane. Zapisywanie inwestycji będzie dostępne po utworzeniu osobnych tabel Robisię.</p><p class="muted">Zmiana bazy wymaga zatwierdzenia przez administratora. Nie zapisano żadnych danych inwestycji.</p>${btn('reload','Sprawdź ponownie','primary')} ${btn('logout','Wyloguj')}<p class="version" style="margin-top:18px">Wersja ${C.VERSION}</p></div>`;
 }else if(/JWT|token|expired|session|401/i.test(e.message)){API.logout();loginView('Sesja wygasła. Zaloguj się ponownie.');}else{$('#app').innerHTML=`<div class="login card"><h1>Nie udało się wczytać danych</h1><div class="notice error">${esc(e.message)}</div>${btn('reload','Spróbuj ponownie','primary')} ${btn('logout','Wyloguj')}</div>`;}}
async function load(){const admin=await API.rpc('cf_is_admin');if(!admin){API.logout();loginView('Dostęp tylko dla administratora.');return;}
 const [rows,settings]=await Promise.all([API.projects(),API.settings()]);all=rows;config=settings[0]||{payload:defaults(),revision:0};all=all.map(row=>({...row,payload:C.captureCatalog(config.payload,row.payload)}));selected=selected?all.find(x=>x.id===selected.id):null;configBaseline=structuredClone(config);projectDirty=false;settingsDirty=restoreDraft('settings',config);const draftKeys=Object.keys(drafts.read()).filter(key=>key.startsWith('project:'));if(!selected&&draftKeys.length){const found=all.find(row=>'project:'+row.id===draftKeys[0]);if(found){selected=structuredClone(found);view='overview';}}if(selected){selected=structuredClone(selected);projectDirty=restoreDraft('project:'+selected.id,selected);}saveError='';updateSaveState();render();if(dirty)scheduleSave();if(selected&&view==='overview')void loadStageInvoices();await openRequestedPurchase();}
async function openRequestedPurchase(){
 const query=new URL(window.location.href).searchParams,requested=query.get('project'),ksef=query.get('purchaseKsef'),invoice=query.get('invoice');if(!requested)return;
 const target=all.find(row=>row.id===requested);if(!target)return;
 selected=structuredClone(target);projectDirty=restoreDraft('project:'+target.id,selected);view=invoice?'payments':ksef?'purchases':['ledger','shopping'].includes(query.get('view'))?query.get('view'):'overview';updateSaveState();render();if(!invoice&&!ksef)return;
 if(invoice){await loadStageInvoices();if((stageInvoiceCache.get(target.id)||[]).some(row=>row.id===invoice))await invoicePaidDialog(invoice);return;}
 const purchase=p().purchases.find(x=>x.sourceKsefNumber===ksef);if(purchase)await purchaseDialog(purchase.id);
}
function render(){closeStock();const side=selected?C.MODULES:[['dashboard','Inwestycje'],['earnings-summary','Podsumowanie zarobków'],['stock','Magazyn'],['catalog','Cennik'],['settings','Dane wykonawcy']];
 $('#app').innerHTML=`<header class="topbar"><div class="row">${btn('menu','Menu','mobile-menu')}${logoMarkup()}<span class="version">Inwestycje remontowe · ${C.VERSION}</span></div><div class="row topbar-actions">${selected&&view==='overview'?'':`<a class="button" data-action="stage-invoice" style="font-size:14px" href="/bill/?new=1&amp;brand=robisie${selected?'&amp;source='+encodeURIComponent(selected.id):''}" target="_blank" rel="noopener">Wystaw fakturę</a>${selected?btn('receipt-add','+ Dodaj wpłatę','primary quick-receipt'): ''}`}<span class="muted" id="save-state">${saveError?'Błąd zapisu — kopia zachowana na urządzeniu':writes.pending?'Zapisywanie…':dirty?'Oczekiwanie na automatyczny zapis':'Dane zapisane w bazie'}</span>${btn('logout','Wyloguj','logout')}</div></header><div class="shell"><nav class="${mobileOpen?'open':''}">${selected?btn('back','Wszystkie inwestycje')+'<p class="muted" style="padding:10px">'+esc(p().name)+'<br>'+esc(selected.contract_number)+'</p>':''}${side.map(([key,label])=>btn('nav',label,view===key?'active':'',`data-view="${key}"`)).join('')}${selected?btn('nav','Cennik',view==='catalog'?'active':'','data-view="catalog"')+btn('nav','Dojazdy',view==='trips'?'active':'','data-view="trips"'):''}</nav><main><div class="toolbar"><div><h1>${title()}</h1><p class="muted">${selected?esc(p().name)+' · '+esc(selected.contract_number):'Robisię — prowadzenie inwestycji'}</p></div><div class="actions">${selected?(view==='overview'?(p()._undo||dirty?undoButton():''):(view==='trips'?'':btn('print','Generuj PDF'))+undoButton()):view==='dashboard'?btn('nav','Podsumowanie zarobków','',`data-view="earnings-summary"`)+btn('nav','Magazyn','',`data-view="stock"`)+btn('new-project','Nowa inwestycja','primary'):['stock','earnings-summary'].includes(view)?'':undoButton()}</div></div>${recoveryNotice()}<div id="content">${content()}</div>${selected&&view!=='overview'?`<div class="savebar"><span class="muted">Zmiany zapisują się automatycznie. Możesz cofnąć ostatni zapis.</span>${undoButton()}</div>`:''}</main></div>`;
 if(view==='stock')void mountStockPanel();
}
function content(){switch(view){case'stock':return '<div id="robisie-stock-panel" class="robisie-stock"><p role="status">Ładowanie towarów…</p></div>';case'earnings-summary':return earningsSummaryView();case'dashboard':return dashboard();case'trips':return tripsView();case'catalog':return catalogView();case'settings':return settingsView();case'ledger':return ledgerView();case'overview':return overview();case'data':return dataView();case'rooms':return roomsView();case'offer':return linesView('offer');case'works':return linesView('works');case'summary':return summaryView();case'payments':return paymentsView();case'shopping':return shoppingView();case'purchases':return purchasesView();case'journal':return journalView();case'contract':return contractView();case'handover':return handoverView();default:return '';}}
const projectFilters=[['','Wszystkie'],['oferta','Oferta'],['przygotowanie','W przygotowaniu'],['prace','Realizowane'],['odbior','Do odbioru'],['zakonczona','Zakończone']];
function projectOrder(a,b){const priority=Number(b.payload.status==='prace')-Number(a.payload.status==='prace');if(priority)return priority;const parts=row=>String(row.contract_number||'').match(/^UUR-RS\/(\d{4})\/(\d{1,2})\/(\d+)$/)?.slice(1).map(Number)||[0,0,0];const left=parts(a),right=parts(b);for(let i=0;i<3;i++){if(left[i]!==right[i])return right[i]-left[i];}return 0;}
function filteredProjects(){const query=projectSearch.trim().toLocaleLowerCase('pl');return all.filter(x=>(!projectFilter||x.payload.status===projectFilter)&&JSON.stringify([x.payload.name,x.payload.investor,x.payload.address,x.contract_number]).toLocaleLowerCase('pl').includes(query)).sort(projectOrder);}
function projectFilterButtons(){return `<div class="project-filters" role="group" aria-label="Filtruj inwestycje według etapu">${projectFilters.map(([key,label])=>btn('project-filter',`${label} <span class="filter-count">${all.filter(x=>!key||x.payload.status===key).length}</span>`,projectFilter===key?'active':'',`data-status="${key}" aria-pressed="${projectFilter===key}"`)).join('')}</div>`;}
function filteredProjectRows(){const rows=filteredProjects();return rows.length?projectRows(rows):'<div class="empty">Brak inwestycji pasujących do wybranych filtrów.</div>';}
function dashboard(){const active=all.filter(x=>x.payload.status!=='zakonczona'),t=active.map(x=>C.totals(x.payload));return `<div class="metrics">${metric('Aktywne inwestycje',active.length,'gold')}${metric('Wartość aktualnych prac',money(t.reduce((s,x)=>s+x.works.after,0)))}${metric('Wpłaty za prace',money(t.reduce((s,x)=>s+x.paid,0)))}${metric('Pozostałe rozliczenie',money(t.reduce((s,x)=>s+x.remaining,0)))}${metric('Zarobione łącznie',money(all.reduce((sum,x)=>sum+C.totals(x.payload).paid,0)),'gold')}<p class="muted metrics-note">Zarobione łącznie: otrzymane wpłaty za prace ze wszystkich inwestycji, bez zaliczek na materiały.</p></div>${card(`<div class="toolbar"><h2>Inwestycje</h2>${projectFilterButtons()}<input id="search-projects" value="${esc(projectSearch)}" placeholder="Szukaj inwestycji, inwestora lub umowy" aria-label="Szukaj inwestycji" style="max-width:360px"></div><div class="project-list" id="project-list">${filteredProjectRows()}</div>`)}${card(`<h2>Wymaga uwagi</h2>${all.flatMap(s=>alerts(s).map(a=>`<p>${btn('open',esc(s.payload.name),'',`data-id="${s.id}"`)} <span class="small">${esc(a)}</span></p>`)).join('')||'<p class="muted">Brak zaległych spraw.</p>'}`)}`;}
function projectRows(rows){return rows.map(s=>`<div class="project" data-action="open" data-project-row="true" data-id="${esc(s.id)}" tabindex="0" role="link" aria-label="Otwórz inwestycję ${esc(s.payload.name)}"><div class="project-info"><h3>${esc(s.payload.name)}</h3><p class="muted" style="margin:0">${esc(s.payload.investor)} · ${esc(s.payload.address||'Adres do uzupełnienia')}<br>${esc(s.contract_number)}</p></div><div class="project-price"><small>${s.payload.status==='zakonczona'?'Kwota końcowa za prace':'Aktualna kwota za prace'}</small><strong>${money(C.finalWorkAmount(s.payload))}</strong></div><div class="row project-actions"><span class="tag ${esc(s.payload.status)}">${statuses[s.payload.status]||esc(s.payload.status)}</span>${s.payload.status==='zakonczona'&&Completion.summary(s.payload).open?'<span class="tag odbior">Do rozliczenia</span>':''}${btn('project-copy','Utwórz nowy na podstawie','',`data-id="${esc(s.id)}"`)}${btn('project-delete','Usuń','danger',`data-id="${esc(s.id)}"`)}</div></div>`).join('')||'<div class="empty">Dodaj pierwszą inwestycję, aby rozpocząć.</div>';}
function copyProjectDialog(id){const source=all.find(x=>x.id===id);if(!source)return;
 modal('Utwórz nowy na podstawie',`<p class="muted">Źródło: ${esc(source.payload.name)} · ${esc(source.contract_number)}</p><div class="grid">${input('name','Nazwa nowej inwestycji',source.payload.name+' — nowe zlecenie','text','required')}${input('investor','Inwestor',source.payload.investor,'text','required')}${input('date','Data nadania nowego numeru',C.today(),'date','required')}</div><h3>Wybierz sekcje do skopiowania</h3><div class="pdf-choices">${C.COPY_SECTIONS.map(([key,label])=>`<label class="pdf-choice"><input type="checkbox" name="copySection" value="${key}" ${['rooms','offer','stages'].includes(key)?'checked':''}><span>${esc(label)}</span></label>`).join('')}</div><p class="muted" style="margin-top:16px">Prace, oferta i dziennik przenoszą również potrzebne pomieszczenia. Nowa inwestycja dostanie własny numer umowy i załączników. Wpłaty, akceptacje, daty wykonania i historia zmian nie są przenoszone. Umowa zostanie utworzona z danych nowej inwestycji.</p>`,async fd=>{
 const sections=fd.getAll('copySection');if(!sections.length)throw new Error('Wybierz przynajmniej jedną sekcję.');
 const payload=C.copyProject(source.payload,sections,fd.get('name'),fd.get('investor'),fd.get('date'));
 const result=await API.createProject(C.captureCatalog(config.payload,payload),fd.get('date'));selected=Array.isArray(result)?result[0]:result;all.unshift(structuredClone(selected));view='data';dirty=false;shopFilter=null;lineFilter='';toast('Utworzono nową inwestycję na podstawie wybranych sekcji.');
 },null,'','Utwórz nową inwestycję');
}
function stagePaid(data,id){return C.effectiveReceipts(data).filter(r=>r.kind==='work'&&r.stageId===id).reduce((s,r)=>s+C.number(r.amount),0);}
function alerts(s){const data=s.payload,t=C.totals(data),list=[];if(data.status==='zakonczona')return list;
 if(data.changes?.some(x=>!x.accepted))list.push('Zmiany zakresu oczekują na akceptację.');
 if(data.stages.some(x=>x.due&&x.due<C.today()&&stagePaid(data,x.id)+.01<t.agreed*C.number(x.percent)/100))list.push('Termin płatności etapu upłynął.');
 if(data.purchases.some(x=>C.purchasePayment(x).remaining>0))list.push('Zakupy wymagają przypisania wpłat.');if(data.status==='odbior')list.push('Inwestycja czeka na odbiór.');return list;}
function importNotes(){const source=p().sourceImport;if(!source)return '';return card(`<details class="import-history"><summary>Historia z ${source.format==='PDF'?'PDF':'Numbers'}</summary><div class="import-history-body"><p>${esc(source.fileName)}</p>${source.sheetNumbers?.length?`<p class="muted">Arkusze: ${esc(source.sheetNumbers.join(', '))}</p>`:''}${source.notes.map(note=>`<p>${esc(note)}</p>`).join('')}</div></details>`);}
function overviewTasks(data,t){
 const tasks=[],unsettled=(data.purchases||[]).filter(x=>C.purchasePayment(x).remaining>.005),missing=(data.purchases||[]).filter(C.purchaseNeedsInvoice);
 if(unsettled.length)tasks.push({title:'Zakupy do rozliczenia: '+unsettled.length,detail:'Pozostało przypisać wpłaty: '+money(unsettled.reduce((sum,x)=>sum+C.purchasePayment(x).remaining,0)),action:'purchases-settle',label:'Rozlicz zakupy'});
 for(const item of missing.slice(0,3))tasks.push({title:'Zakup wymaga faktury',detail:(item.shop||'Bez sklepu')+' · '+money(item.amount)+' · '+(item.description||'Zakup'),action:'purchase-edit',id:item.id,label:'Uzupełnij dokument'});
 if(missing.length>3)tasks.push({title:'Pozostałe zakupy bez faktury: '+(missing.length-3),detail:'Sprawdź dokumenty przy pozostałych kosztach.',action:'nav',view:'purchases',label:'Sprawdź zakupy'});
 const changes=(data.changes||[]).filter(x=>!x.accepted);
 if(changes.length)tasks.push({title:'Zmiany zakresu do akceptacji: '+changes.length,detail:'Sprawdź zmienione prace i potwierdzenie inwestora.',action:'nav',view:'works',label:'Sprawdź zmiany'});
 const overdue=(data.stages||[]).filter(x=>x.due&&x.due<C.today()&&stagePaid(data,x.id)+.01<t.agreed*C.number(x.percent)/100);
 if(overdue.length)tasks.push({title:'Etapy po terminie płatności: '+overdue.length,detail:overdue.map(x=>x.name).join(', '),action:'settlement-open',label:'Sprawdź rozliczenie'});
 if(data.status==='odbior')tasks.push({title:'Inwestycja czeka na odbiór',detail:'Sprawdź wykonane prace, materiały i końcowe rozliczenie.',action:'finish',label:'Zakończ inwestycję'});
 if(data.status==='zakonczona'&&Completion.summary(data).open)tasks.push({title:'Zakończona inwestycja ma otwarte rozliczenie',detail:'Sprawdź pozostałą dopłatę lub kwotę do zwrotu inwestorowi.',action:'completion-review',label:'Rozliczenie końcowe'});
 return tasks;
}
function overviewEvents(data,invoices){
 const events=[];let sequence=0;
 const add=event=>events.push({...event,sequence:sequence++});
 for(const item of data.purchases||[]){
  const adjustments=(item.ksefCorrections||[]).reduce((sum,c)=>sum+C.number(c.amount),0);
  add({date:item.date||'',kind:'Zakup',title:item.shop||'Zakup materiałów',detail:[item.description,item.invoice].filter(Boolean).join(' · '),amount:C.number(item.amount)-adjustments,action:'purchase-edit',id:item.id,label:'Otwórz zakup'});
  for(const correction of item.ksefCorrections||[])add({date:correction.date||'',kind:'Korekta kosztu',title:correction.number||'Korekta zakupu',detail:item.shop||item.description||'',amount:C.number(correction.amount),action:'purchase-edit',id:item.id,label:'Zobacz korektę'});
 }
 for(const receipt of C.receiptRows(data)){
  const invoice=receipt.invoiceId&&invoices.find(r=>r.id===receipt.invoiceId);
  const target=receipt.invoiceId?(invoice?{action:'invoice-allocate',id:invoice.id}:{action:'nav',view:'payments'}):receipt.purchaseId?{action:'purchase-edit',id:receipt.purchaseId}:{action:'receipt-edit',id:receipt.id};
  add({date:receipt.date||'',kind:'Wpłata',title:receipt.kindLabel||'Wpłata inwestora',detail:receipt.note||receipt.stageLabel||'',amount:C.number(receipt.amount),...target,label:'Zobacz wpłatę'});
 }
 for(const row of invoices.filter(r=>r.originKind!=='purchases')){
  let amount=null;try{amount=row.externalKsef&&row.grossAmount!=null?C.number(row.grossAmount):BI.amount(row);}catch{}
  add({date:row.payload?.issueDate||'',kind:row.status==='draft'?'Szkic faktury':row.payload?.correction?'Korekta faktury':'Faktura',title:row.number||'Szkic bez numeru',detail:row.payload?.buyer?.name||'',amount,currency:row.payload?.currency||'PLN',href:invoiceHref(row),label:'Otwórz w Bill'});
 }
 for(const entry of data.journal||[])add({date:entry.date||'',kind:'Dziennik',title:'Wpis w dzienniku prac',detail:entry.description||'',amount:null,action:'journal-edit',id:entry.id,label:'Otwórz wpis'});
 return events.sort((a,b)=>String(b.date).localeCompare(String(a.date))||b.sequence-a.sequence).slice(0,6);
}
function overviewAction(item){const attrs=(item.id?'data-id="'+esc(item.id)+'" ':'')+(item.view?'data-view="'+esc(item.view)+'"':'');return item.href?`<a class="button" data-action="stage-invoice" href="${esc(item.href)}" target="_blank" rel="noopener">${esc(item.label)}</a>`:btn(item.action,esc(item.label),'',attrs);}
let ledgerCategory='',ledgerSearch='',ledgerDateFilter='all';
function ledgerView(){
 const s=C.settlementTotals(p()),rows=s.rows.filter(row=>(!ledgerCategory||row.category===ledgerCategory)&&(!ledgerSearch||JSON.stringify([row.description,row.category]).toLocaleLowerCase('pl').includes(ledgerSearch.toLocaleLowerCase('pl')))&&(ledgerDateFilter!=='undated'||!row.date));
 return `${card(`<div class="toolbar"><div><h2>Wspólne saldo wszystkich rozliczeń</h2><p class="muted">Wpłaty, potrącenia, prace, zakupy i zwroty są liczone wspólnie. Dodatnie saldo oznacza środki pozostałe w rozliczeniu; ujemne — kwotę do dopłaty.</p><p class="muted">Przy wspólnej puli podział w pozostałych widokach jest analityczny: najpierw koszty zakupów, a reszta na prace. Nie tworzy dodatkowych wpłat.</p></div>${btn('ledger-add','Dodaj transakcję','primary')}</div><div class="metrics">${metric('Saldo wspólne',money(s.balance),'gold')}${metric('Wpłaty i zwroty przed potrąceniami',money(s.plus))}${metric('Prace i wydatki',money(s.expenses))}${metric('Potrącenia',money(s.withheld))}</div>${s.undated?`<p class="notice">${s.undated} pozycji bez pełnej daty. Datowane są ułożone chronologicznie, a pozostałe zachowują kolejność źródłową. Import nie odtwarza historii edycji komórek.</p>`:''}${s.unexplained?`<p class="notice">Do wyjaśnienia: ${s.unexplained} pozycji.</p>`:''}`)}${card(`<h2>Podsumowanie kategorii</h2>${table(['Kategoria','Pozycji','Plus','Minus'],s.groups.map(g=>`<tr><td>${esc(g.category)}</td><td>${g.count}</td><td class="num">${money(g.plus)}</td><td class="num">${money(g.minus)}</td></tr>`).join(''))}`)}${card(`<div class="row"><label>Kategoria <select id="ledger-category"><option value="">Wszystkie</option>${s.groups.map(g=>`<option ${ledgerCategory===g.category?'selected':''}>${esc(g.category)}</option>`).join('')}</select></label><label>Daty <select id="ledger-dates"><option value="all">Wszystkie</option><option value="undated" ${ledgerDateFilter==='undated'?'selected':''}>Do uzupełnienia</option></select></label><input id="ledger-search" value="${esc(ledgerSearch)}" placeholder="Szukaj opisu" aria-label="Szukaj transakcji"></div><p class="muted">Saldo po pozycji dotyczy całego rozliczenia, także przy aktywnym filtrze.</p>${table(['Data','Opis','Kategoria','Plus','Minus','Saldo wspólne',''],rows.map(row=>`<tr><td>${esc(row.date||row.dateHint||'Data do uzupełnienia')}</td><td>${esc(row.description)}${row.needsExplanation?'<br><strong>Do wyjaśnienia</strong>':''}</td><td>${esc(row.category)}</td><td class="num">${row.plus?money(row.plus):'—'}</td><td class="num">${row.minus?money(row.minus):'—'}</td><td class="num">${money(row.balance)}</td><td>${['works','purchases','receipts'].includes(row.kind)?btn('ledger-edit','Edytuj','',`data-kind="${row.kind}" data-id="${esc(row.id.replace(/:withheld$/,''))}"`):''}</td></tr>`).join(''))}`)}`;
}
function ledgerDialog(kind,id){
 const old=kind&&id?p()[kind]?.find(x=>x.id===id):null;
 if(id&&!old)throw Error('Nie znaleziono transakcji.');
 if(kind==='purchases'&&old?.sourceKsefNumber){void purchaseDialog(id);return;}
 if(kind==='receipts'&&(p().invoiceSettlements||[]).some(i=>(i.existingReceipts||[]).some(r=>r.id===id))){throw Error('Wpłata jest powiązana z fakturą. Najpierw popraw jej powiązanie w Etapach i płatnościach.');}
 const category=old?.settlementCategory||old?.category||(kind==='purchases'?'Materiały i zakupy':'Wpłaty');
 const amount=kind==='receipts'?C.round(C.number(old?.amount)+C.number(old?.settlementWithheld)):kind==='works'?C.lineValue(old):old?.charge??'';
 const categories=C.categoryNames(['Wpłaty','Zwroty — Włochy','Zadaszenie — robocizna','Zadaszenie — materiały','Inne rozliczenia','Do wyjaśnienia',...C.settlementTotals(p()).groups.map(g=>g.category)]);
 modal(id?'Edytuj transakcję rozliczenia':'Dodaj transakcję rozliczenia',`<div class="grid"><div class="field"><label for="f-ledgerKind">Rodzaj</label><select id="f-ledgerKind" name="ledgerKind" ${id?'disabled':''}><option value="receipts" ${!kind||kind==='receipts'?'selected':''}>Wpłata / zwrot otrzymany</option><option value="works" ${kind==='works'?'selected':''}>Wykonana praca / usługa</option><option value="purchases" ${kind==='purchases'?'selected':''}>Wydatek / zakup / inne obciążenie</option></select></div>${input('ledgerDate','Data',id?old.date||old.workDate||'':C.today(),'date')}${input('ledgerAmount','Kwota przed potrąceniem (zł)',amount,'number','required')}${input('ledgerRate','Potrącenie wpłaty (%)',old?.settlementRate||0,'number','required')}<div class="field"><label for="f-ledgerCategory">Kategoria</label><input id="f-ledgerCategory" name="ledgerCategory" list="ledger-categories" value="${esc(category)}" required><datalist id="ledger-categories">${categories.map(name=>`<option value="${esc(name)}">`).join('')}</datalist></div></div>${text('ledgerDescription','Opis',old?.note||old?.name||old?.description||'','required')}<label class="inline-check"><input type="checkbox" name="ledgerExplain" ${old?.needsExplanation?'checked':''}> Wymaga wyjaśnienia</label><p class="muted">Potrącenie dotyczy tylko wpłat. Wydatki są zapisywane jako koszt inwestora, bez tworzenia dodatkowej wpłaty. Brak daty pozostaje oznaczony.</p>`,fd=>{
  const type=kind||fd.get('ledgerKind'),amount=C.round(C.number(fd.get('ledgerAmount'))),date=fd.get('ledgerDate')||'',description=String(fd.get('ledgerDescription')||'').trim(),category=String(fd.get('ledgerCategory')||'').trim();
  if(amount<=0||!description||!category)throw Error('Uzupełnij dodatnią kwotę, opis i kategorię.');
  let item;if(type==='receipts')item=C.settlementReceipt({gross:amount,rate:fd.get('ledgerRate'),date,category,description,needsExplanation:fd.has('ledgerExplain')},old||{});
  else if(type==='works'){if(old&&(C.number(old.qty)!==1||C.number(p().workDiscount??p().discount)!==0))throw Error('Złożoną pozycję edytuj w Kalkulacji końcowej.');item={...old,id:old?.id||C.uid(),date,workDate:date,name:description,category,settlementCategory:category,unit:'kpl',qty:1,price:amount,included:true,done:true,roomId:old?.roomId||'',serviceId:old?.serviceId||'',needsExplanation:fd.has('ledgerExplain'),dateHint:date?'':old?.dateHint||''};}
  else if(type==='purchases'){if(old&&(C.invoicePurchasePaid(old)||C.receiptPurchasePaid(old)||old.ksefCorrections?.length))throw Error('Powiązany zakup edytuj w Zakupach i materiałach.');item={...old,id:old?.id||C.uid(),date,description,shop:old?.shop||category,amount,charge:amount,...(old?{}:{paid:false,paidAmount:0}),settlementCategory:category,needsExplanation:fd.has('ledgerExplain'),dateHint:date?'':old?.dateHint||''};}
  else throw Error('Nieprawidłowy rodzaj transakcji.');
  if(id)p()[type]=p()[type].map(x=>x.id===id?item:x);else p()[type].push(item);p().mixedSettlement=true;markDirty();
 },id?()=>{if(kind==='receipts'){const next=changeReceipt(id,null);if(!next)throw Error('Nie można usunąć powiązanej wpłaty.');selected.payload=next;}else{if(old.sourceKsefNumber||old.ksefCorrections?.length||C.invoicePurchasePaid(old)||C.receiptPurchasePaid(old))throw Error('Powiązaną pozycję usuń w module źródłowym.');p()[kind]=p()[kind].filter(x=>x.id!==id);}markDirty();}:null);
}

function overview(){
 const data=p(),t=C.totals(data),closed=data.status==='zakonczona',invoices=stageInvoiceCache.get(selected.id)||[],tasks=overviewTasks(data,t),events=overviewEvents(data,invoices),received=C.round(t.paid+t.materials.advances);
 const tile=(label,value,detail,tone='')=>`<article class="panel-metric ${tone}"><span>${label}</span><strong>${money(value)}</strong><small>${detail}</small></article>`;
 return `<div class="investment-panel">${shoppingNotice()}
  <section class="card panel-actions" aria-label="Szybkie działania"><div class="panel-section-heading"><h2>Szybkie działania</h2><span class="tag ${esc(data.status)}">${esc(statuses[data.status]||data.status)}</span></div><div class="panel-action-buttons">
   <a class="button primary" data-action="stage-invoice" href="/bill/?new=1&amp;brand=robisie&amp;source=${encodeURIComponent(selected.id)}" target="_blank" rel="noopener">Wystaw fakturę</a>
   ${btn('nav','Do kupienia','','data-view="shopping"')}${btn('purchase-add','Dodaj koszt / zakup')}${btn('receipt-add','Dodaj wpłatę')}${btn('purchases-settle','Rozlicz zakupy')}${btn('print','Generuj PDF')}${btn(closed?'completion-review':'finish',closed?'Rozliczenie końcowe':'Zakończ inwestycję','panel-finish')}
  </div><div class="panel-secondary-actions">${data.mixedSettlement?btn('nav','Wspólne rozliczenie — '+money(C.settlementTotals(data).balance),'primary','data-view="ledger"'):''}${btn('journal-add','+ Wpis do dziennika')}${btn('trip-add','+ Dodaj dojazd')}${btn('settlement-open','Rozliczenie inwestycji')}</div></section>
  ${data.mixedSettlement?card(`<h2>Wspólne rozliczenie — wszystkie kategorie</h2><div class="metrics">${metric('Saldo wspólne',money(C.settlementTotals(data).balance),'gold')}${metric('Wpłaty przed potrąceniami',money(C.settlementTotals(data).plus))}${metric('Prace i wydatki',money(C.settlementTotals(data).expenses))}${metric('Potrącenia',money(C.settlementTotals(data).withheld))}</div>${btn('nav','Otwórz pełne rozliczenie','primary','data-view="ledger"')}<p class="muted">Dodatnie saldo to pozostałe środki wspólne; ujemne — kwota do dopłaty. Wszystkie kategorie są rozliczane razem.</p>`):''}
  <section class="panel-finances" ${data.mixedSettlement?'hidden style="display:none"':''} aria-label="Podsumowanie finansowe"><div class="panel-metrics">
   ${tile('Wykonane prace',t.works.done,'Wartość prac oznaczonych jako wykonane')}
   ${tile('Otrzymane wpłaty',received,'Za prace: '+money(t.paid)+' · na materiały: '+money(t.materials.advances))}
   ${tile(t.remaining<0?'Nadpłata inwestora':'Pozostało do zapłaty',Math.abs(t.remaining),'Rozliczenie wykonanych prac i materiałów','panel-metric-main')}
   ${tile(t.materials.balance<0?'Dopłata na materiały':'Saldo materiałów',Math.abs(t.materials.balance),t.materials.balance<0?'Koszty przewyższają otrzymane zaliczki':t.materials.balance>0?'Zaliczka do wykorzystania lub zwrotu':'Koszty i zaliczki są wyrównane')}
  </div><details class="panel-financial-details"><summary>Szczegóły finansowe</summary><div class="panel-detail-grid"><p>Uzgodniona oferta<strong>${money(t.agreed)}</strong></p><p>Aktualna kalkulacja<strong>${money(t.works.after)}</strong></p><p>Faktyczne wydatki na materiały<strong>${money(t.materials.spent)}</strong></p><p>Koszt materiałów dla inwestora<strong>${money(t.materials.charged)}</strong></p></div></details></section>
  <div class="panel-workspace"><section class="card panel-tasks"><div class="panel-section-heading"><h2>Do zrobienia</h2><span class="panel-count">${tasks.length}</span></div>${tasks.map(task=>`<article class="panel-task"><div><strong>${esc(task.title)}</strong><p>${esc(task.detail)}</p></div>${overviewAction(task)}</article>`).join('')||'<p class="panel-empty">Brak spraw wymagających uwagi.</p>'}</section>
  <section class="card panel-activity"><div class="panel-section-heading"><h2>Ostatnie zdarzenia</h2>${btn('invoices-refresh','Odśwież','panel-refresh')}</div>${stageInvoiceErrors.has(selected.id)?'<p class="notice">Nie udało się odświeżyć faktur. Pokazujemy zapisane dane inwestycji i ostatnio wczytane dokumenty.</p>':!stageInvoiceCache.has(selected.id)?'<p class="muted small">Faktury pojawią się po odświeżeniu dokumentów.</p>':''}<div class="panel-event-list">${events.map(event=>`<article class="panel-event"><div class="panel-event-heading"><span>${esc(event.kind)} · ${event.date?date(event.date):'Brak daty'}</span>${event.amount==null?'':`<strong>${esc(new Intl.NumberFormat('pl-PL',{style:'currency',currency:/^[A-Z]{3}$/.test(event.currency||'')?event.currency:'PLN'}).format(event.amount))}</strong>`}</div><strong>${esc(event.title)}</strong>${event.detail?`<p>${esc(event.detail.length>150?event.detail.slice(0,150)+'…':event.detail)}</p>`:''}${overviewAction(event)}</article>`).join('')||'<p class="panel-empty">Tutaj pojawią się zakupy, wpłaty, faktury i wpisy w dzienniku.</p>'}</div></section></div>
  <details class="card panel-documents"><summary>Dokumenty inwestycji</summary><div class="panel-document-body">${table(['Dokument','Numer'],documents().map(([name,num])=>`<tr><td>${name}</td><td>${esc(num)}</td></tr>`).join(''))}<div class="actions">${btn('print','Wybierz dokumenty i generuj PDF')}</div></div></details>
  ${importNotes()}
 </div>`;
}
function dataView(){const d=p();return card(`<div class="grid">${field('name','Nazwa inwestycji',d.name,'text','required')}${field('investor','Imię i nazwisko inwestora',d.investor,'text','required')}${field('investorAddress','Adres zamieszkania inwestora',d.investorAddress)}${field('address','Adres inwestycji',d.address)}${field('phone','Telefon',d.phone,'tel')}${field('email','E-mail',d.email,'email')}${field('pesel','PESEL (opcjonalnie)',d.pesel)}<div class="field"><label for="status">Etap inwestycji</label><select id="status" data-field="status">${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${k===d.status?'selected':''}>${v}</option>`).join('')}</select></div>${field('startDate','Planowane rozpoczęcie',d.startDate,'date')}${field('endDate','Planowane zakończenie',d.endDate,'date')}</div><p class="muted">Numer umowy ${esc(selected.contract_number)} został nadany podczas tworzenia inwestycji i pozostaje stały.</p>`);}
function roomsView(){const areas=p().rooms.map(C.roomArea),measure=C.measurement;return `<div class="metrics">${metric('Powierzchnia podłóg',measure(areas.reduce((sum,x)=>sum+x.floor,0))+' m²')}${metric('Powierzchnia sufitów',measure(areas.reduce((sum,x)=>sum+x.ceiling,0))+' m²')}${metric('Powierzchnia ścian',measure(areas.reduce((sum,x)=>sum+x.walls,0))+' m²')}</div>${card(`<div class="toolbar"><h2>Pomieszczenia i wymiary</h2>${btn('room-add','Dodaj pomieszczenie','primary')}</div><p class="muted">Wymiary i powierzchnie pokazujemy z dwoma miejscami po przecinku, zaokrąglonymi w górę.</p>${table(['Pomieszczenie','Wymiary: dł. × szer. × wys.','Podłoga','Sufit','Ściany','Obwód',''],p().rooms.map(r=>{const a=C.roomArea(r),parts=r.parts?.length?r.parts:[r];return `<tr class="room-row"><td><strong>${esc(r.name)}</strong>${parts.length>1?`<small class="room-part-count">${parts.length} części pomieszczenia</small>`:''}</td><td class="room-dimensions">${parts.map((part,i)=>`<div>${parts.length>1?`<span class="muted">Część ${i+1}: </span>`:''}${measure(part.length)} × ${measure(part.width)} × ${measure(part.height??r.height)} m</div>`).join('')}</td><td class="num">${measure(a.floor)} m²</td><td class="num">${measure(a.ceiling)} m²</td><td class="num">${measure(a.walls)} m²</td><td class="num">${measure(a.perimeter)} m</td><td>${btn('room-edit','Edytuj','',`data-id="${esc(r.id)}"`)}</td></tr>`;}).join(''))}`)}`;}

function workGroups(lines){
 const categoryKey=value=>String(value||'Pozostałe prace').trim().replace(/\s+/g,' ').toLocaleLowerCase('pl');
 const order=new Map(),names=new Map();for(const service of currentCatalog()){const key=categoryKey(service.category);if(!order.has(key)){order.set(key,order.size);names.set(key,String(service.category||'Pozostałe prace').trim());}}
 const groups=new Map();for(const line of lines){const key=categoryKey(line.category);if(!groups.has(key))groups.set(key,{name:names.get(key)||String(line.category||'Pozostałe prace').trim(),lines:[]});groups.get(key).lines.push(line);}
 return [...groups].sort(([a],[b])=>(order.get(a)??Infinity)-(order.get(b)??Infinity)||a.localeCompare(b,'pl')).map(([,group])=>[group.name,group.lines]);
}
function roomLines(kind,rows){const groups=new Map(p().rooms.map(r=>[r.id,[]]));for(const line of rows){const id=line.roomId||'';if(!groups.has(id))groups.set(id,[]);groups.get(id).push(line);}const isWork=kind==='works';return [...groups].filter(([,items])=>items.length).map(([roomId,items])=>{const key=JSON.stringify([selected.id,kind,roomId]);return `<details class="service-category room-lines" data-room-group="${esc(key)}" ${openRoomGroups.has(key)?'open':''}><summary><span>${esc(roomName(roomId))}</span><small>${isWork?money(C.roomWorkAmount(p(),roomId)):items.length+' poz.'}</small></summary><div class="category-items">${table(['Zakres','Praca','Jedn.','Ilość','Cena (zł)','Wartość',...(isWork?['Wykonane']:[]),''],workGroups(items).map(([category,categoryLines])=>`<tr class="work-category-row"><th colspan="${isWork?8:7}" scope="rowgroup"><div class="row"><strong>${esc(category)}</strong><small>${categoryLines.length} poz.</small></div></th></tr>`+categoryLines.map(l=>`<tr><td><input type="checkbox" aria-label="Uwzględnij ${esc(l.name)}" data-line="${l.id}" data-kind="${kind}" data-prop="included" ${l.included!==false?'checked':''}></td><td><span class="line-name">${esc(l.name)}</span></td><td>${esc(l.unit||'—')}</td><td><input class="short" type="text" data-numeric="true" inputmode="text" autocomplete="off" spellcheck="false" title="Możesz wpisać liczbę lub działanie, np. 25+3+7-2" min="0" step="0.001" aria-label="Ilość ${esc(l.name)}" value="${l.qty}" data-line="${l.id}" data-kind="${kind}" data-prop="qty"></td><td><input class="price" type="text" data-numeric="true" inputmode="text" autocomplete="off" spellcheck="false" title="Możesz wpisać liczbę lub działanie, np. 25+3+7-2" min="0" step="0.01" aria-label="Cena ${esc(l.name)}" value="${l.price}" data-line="${l.id}" data-kind="${kind}" data-prop="price"></td><td class="num">${money(C.lineValue(l))}</td>${isWork?`<td><input type="checkbox" aria-label="Wykonano ${esc(l.name)}" data-line="${l.id}" data-kind="${kind}" data-prop="done" ${l.done?'checked':''}></td>`:''}<td>${btn('line-edit','Edytuj','',`data-kind="${kind}" data-id="${l.id}"`)}</td></tr>`).join('')).join(''))}</div></details>`;}).join('')||'<div class="empty">Brak pozycji. Dodaj pracę do pomieszczenia.</div>';}
function linesView(kind){const isWork=kind==='works',list=p()[kind],t=C.workTotals(list,isWork?p().workDiscount:p().discount,p().sourceCalculation?.[kind]),rows=list.filter(l=>!lineFilter||l.roomId===lineFilter);
 return `${isWork&&p().activeOfferVersion!=null&&C.activeOffer(p())?`<p class="muted">Oferta obowiązująca: <strong>V${C.activeOffer(p()).version}</strong>. Wersję wybierasz w ofercie wstępnej.</p>`:''}<div class="metrics">${metric('Przed rabatem',money(t.before))}${metric(t.sourceAmountApplied?'Uzgodniona kwota historyczna':'Po rabacie',money(t.after),'gold')}${isWork?metric('Wykonane prace',money(t.done)):metric('Szacowany materiał',money(p().materialEstimate))}${metric('Planowany czas',C.quantity(t.hours)+' godz.')}</div>${card(`<div class="toolbar"><div class="row"><select id="line-room" style="width:auto" aria-label="Filtr pomieszczenia"><option value="">Wszystkie pomieszczenia</option>${p().rooms.map(r=>`<option value="${r.id}" ${r.id===lineFilter?'selected':''}>${esc(r.name)}</option>`).join('')}</select>${btn('line-add','Dodaj pracę','primary',`data-kind="${kind}"`)}</div>${!isWork?btn('accept-offer','Zapisz zaakceptowaną ofertę'):''}</div><p class="muted small">W polach liczbowych możesz wpisywać działania, np. 25+3+7−2.</p><div class="grid">${field(isWork?'workDiscount':'discount','Rabat (%)',isWork?p().workDiscount:p().discount,'number','min="0" max="100" step="0.01"')}${!isWork?field('materialEstimate','Szacunkowy koszt materiału (zł)',p().materialEstimate,'number','min="0" step="0.01"'):''}</div>${t.sourceAmountApplied?'<p class="muted">Kwota historyczna potwierdzona przy imporcie. Szczegółowe pozycje zachowano ze źródła. Zmiana ilości, cen, zakresu lub rabatu uruchomi ponowne obliczenie.</p>':''}${roomLines(kind,rows)}`)}${!isWork?offerHistory():changesView()}`;
}
function offerHistory(){return card(`<h2>Zaakceptowane wersje</h2>${p().acceptedOffers.length?'<p class="muted">Zaznacz wersję obowiązującą dla kalkulacji końcowej i rozliczenia. Nowa zaakceptowana wersja zostaje wybrana automatycznie. Każda wersja zachowuje własną kalkulację oraz oznaczenia wykonania.</p>':''}${p().acceptedOffers.map(o=>`<div class="history"><div class="row"><label class="row offer-version-choice"><input type="radio" name="active-offer" data-action="offer-select" data-version="${o.version}" ${p().activeOfferVersion===o.version?'checked':''} aria-label="Wybierz ofertę V${o.version} do kalkulacji końcowej"><strong>V${o.version} · ${esc(C.attachment(selected,'OFE',o.version))}</strong></label><span class="muted">${date(o.date)} · ${money(C.acceptedAmount(o))}${p().activeOfferVersion===o.version?' · Obowiązująca':''}</span>${btn('offer-print','PDF / drukuj','',`data-version="${o.version}"`)}</div></div>`).join('')||'<p class="muted">Nie zapisano jeszcze zaakceptowanej oferty.</p>'}`);}
function changesView(){return card(`<h2>Historia zmian zakresu</h2><p class="muted">Zapis obejmuje zmiany ilości, cen i zakresu. Oznaczenie wykonania nie wymaga osobnej akceptacji.</p>${p().changes.slice().reverse().map(c=>`<div class="history"><strong>${esc(c.name)}</strong><p class="muted">${date(c.date)} · ${esc(roomName(c.roomId))} · ${money(c.before?C.lineValue(c.before):0)} → ${money(c.after?C.lineValue(c.after):0)}</p><div class="row"><span class="tag">${c.accepted?'Zaakceptowano '+date(c.acceptedDate):'Oczekuje na akceptację'}</span>${!c.accepted?btn('change-accept','Oznacz akceptację inwestora','',`data-id="${c.id}"`):''}</div></div>`).join('')||'<p class="muted">Brak zmian względem zapisanej kalkulacji.</p>'}`);}
function historicSummary(){const rows=p().sourceImport?.summarySnapshot;if(!rows?.length)return '';return card(`<details><summary>Oryginalne podsumowanie z Numbers</summary><p class="muted">Zapis historyczny podsumowania z Numbers. Zawiera również pozycje wyłączone z końcowej kalkulacji; nie zwiększa bieżącego rozliczenia.</p>${table(['Kategoria','Praca','Ilość','Wartość ze źródła'],rows.map(r=>`<tr><td>${esc(r['0'])}</td><td>${esc(r['1'])}</td><td>${C.quantity(r['4'])}</td><td>${money(r['5'])}</td></tr>`).join(''))}</details>`);}
function summaryView(){const d=p(),areas=d.rooms.map(C.roomArea),t=C.totals(d),heads=[['category','Kategoria'],['name','Praca'],['unit','Jednostka'],['qty','Ilość'],['value','Wartość przed rabatem']].map(([key,label])=>({sort:summarySort.key===key?(summarySort.direction===1?'ascending':'descending'):'none',html:btn('summary-sort',label+(summarySort.key===key?(summarySort.direction===1?' ↑':' ↓'):''),'sort-button',`data-key="${key}"`)}));return `<div class="metrics">${metric('Oferta uzgodniona',money(t.agreed))}${metric('Aktualny zakres',money(t.works.after),'gold')}${metric('Zmiana względem oferty',money(t.change))}</div>${card(`<h2>Łączne ilości usług</h2>${table(heads,C.sortSummary(C.aggregate(d.works),summarySort.key,summarySort.direction).map(r=>`<tr><td>${esc(r.category)}</td><td>${esc(r.name)}</td><td>${esc(r.unit||'—')}</td><td class="num">${C.quantity(r.qty)}</td><td class="num">${money(r.value)}</td></tr>`).join(''))}<p class="muted" style="margin-top:14px">Rabat kalkulacji końcowej: ${C.quantity(d.workDiscount)}%. Razem po rabacie: ${money(t.works.after)}.</p>`)}${card(`<h2>Powierzchnie</h2>${table(['Rodzaj','Powierzchnia'],[['Podłogi',areas.reduce((s,a)=>s+a.floor,0)],['Sufity',areas.reduce((s,a)=>s+a.ceiling,0)],['Ściany',areas.reduce((s,a)=>s+a.walls,0)]].map(([name,q])=>`<tr><td>${name}</td><td>${C.quantity(q)} m²</td></tr>`).join(''))}`)}${historicSummary()}`;}
function invoiceList(){
 const documents=(stageInvoiceCache.get(selected.id)||[]).filter(r=>r.number&&r.status!=='draft'),rows=documents.filter(r=>r.originKind!=='purchases'),purchases=documents.filter(r=>r.originKind==='purchases');
 const documentAmount=row=>esc((row.grossAmount??BI.amount(row)).toLocaleString('pl-PL',{style:'currency',currency:row.payload.currency||'PLN'}));
 const sales=card(`<div class="toolbar"><h2>Faktury sprzedażowe i wpłaty inwestora</h2><a class="button" href="/bill/?ksef=1" target="_blank" rel="noopener">Przypisz z KSeF</a>${btn('invoices-refresh','Odśwież faktury')}<a class="button" href="/bill/?new=1&brand=robisie&source=${encodeURIComponent(selected.id)}" target="_blank" rel="noopener">Wystaw fakturę</a></div><p class="muted">Faktury sprzedażowe rozliczają pieniądze od inwestora: materiały, zaliczki na przyszłe zakupy i robociznę. Rozliczenie zwiększają wyłącznie faktycznie otrzymane kwoty. Wcześniej odnotowaną wpłatę powiąż z fakturą, aby nie dodać jej drugi raz.</p>${table(['Faktura','Kwota','Przypisano','Otrzymano',''],rows.map(row=>{const record=(p().invoiceSettlements||[]).find(r=>r.id===row.id);return `<tr><td><a href="${invoiceHref(row)}" target="_blank" rel="noopener">${esc(row.number)}</a>${row.externalKsef?'<br>Sprzedażowa z KSeF':''}${row.costAdjustment?'<br>Odliczono od kosztów: '+money(-C.number(row.costAdjustment.amount)):row.referenceOnly?'<br>Dokument do osobnego rozliczenia':''}${row.payload.correction?'<br>Korekta':''}</td><td>${documentAmount(row)}</td><td>${money(BI.assigned(record))}</td><td>${money(BI.paid(record))}</td><td>${!row.referenceOnly&&!row.payload.correction&&row.payload.currency==='PLN'?`<div class="actions">${btn('invoice-paid',BI.paid(record)>=BI.amount(row)?'Zapłacona ✓':'Zapłacona','primary',`data-id="${esc(row.id)}" ${BI.paid(record)>=BI.amount(row)?'disabled':''}`)}${btn('invoice-allocate','Rozliczenie','',`data-id="${esc(row.id)}"`)}</div>`:''}</td></tr>`;}).join(''))}${!rows.length?'<p class="muted">Brak faktur sprzedażowych powiązanych z tą inwestycją.</p>':''}`);
 return sales+(purchases.length?card(`<h2>Dokumenty zakupowe z KSeF — koszty materiałów</h2><p class="muted">Te dokumenty zapisują zakupy. Ich przypisanie nie zwiększa zaliczek od inwestora. Pozycje i koszt inwestycji edytujesz w „Zakupach i materiałach”.</p>${table(['Faktura zakupowa','Kontrahent','Kwota dokumentu',''],purchases.map(row=>{const purchase=p().purchases.find(x=>x.sourceKsefNumber===row.ksef_number);return `<tr><td><a href="${invoiceHref(row)}" target="_blank" rel="noopener">${esc(row.number)}</a>${row.costAdjustment?'<br>Odliczono od kosztów: '+money(-C.number(row.costAdjustment.amount)):row.referenceOnly?'<br>Dokument do osobnego rozliczenia':''}</td><td>${esc(row.payload.seller?.name||purchase?.shop||'—')}</td><td>${documentAmount(row)}</td><td>${purchase?btn('purchase-edit','Edytuj zakup','',`data-id="${esc(purchase.id)}"`):''}</td></tr>`;}).join(''))}`):'');
}
async function invoicePaidDialog(id){
 await loadStageInvoices();const row=(stageInvoiceCache.get(selected.id)||[]).find(r=>r.id===id);if(!row)throw Error('Nie znaleziono faktury. Odśwież listę.');
 const baseline=structuredClone(selected),record=(p().invoiceSettlements||[]).find(r=>r.id===id),remaining=Math.max(0,C.round(BI.amount(row)-BI.paid(record))),earlier=C.effectiveReceipts(p()).filter(r=>!r.invoiceId&&C.number(r.amount)>0);
 if(!remaining){toast('Ta faktura jest już zapłacona w całości.');return;}
 modal('Zapłacona — '+esc(row.number),`<p>Do potwierdzenia pozostało: <strong>${money(remaining)}</strong>.</p>${input('paidAmount','Otrzymana kwota (zł)',remaining,'number','min="0" step="0.01" required')}${input('paidDate','Data wpływu',C.today(),'date','required')}<label class="field">Wpłata na<select name="paidKind"><option value="materials">Materiały — do rozliczenia zakupów</option><option value="work">Robocizna</option></select></label>${earlier.length?`<details><summary>Ta wpłata jest już zapisana jako zaliczka?</summary><p class="muted">Zaznacz ją tutaj. Kwota nowej wpłaty zmniejszy się automatycznie.</p>${earlier.map(r=>`<label class="inline-check"><input type="checkbox" name="paidReceipt" value="${esc(r.id)}">${money(r.amount)} · ${date(r.date)} · ${esc(r.note||'Wpłata')}</label>`).join('')}</details>`:''}`,fd=>{
  if(selected.id!==baseline.id||selected.revision!==baseline.revision)throw Error('Inwestycja zmieniła się. Otwórz potwierdzenie ponownie.');
  selected.payload=BI.markPaid(baseline.payload,row,{amount:C.number(fd.get('paidAmount')),date:fd.get('paidDate'),kind:fd.get('paidKind'),receiptIds:fd.getAll('paidReceipt')});markDirty();const now=BI.paid(selected.payload.invoiceSettlements.find(r=>r.id===id));return `Faktura ${row.number}: otrzymano ${money(now)} z ${money(BI.amount(row))}; do zapłaty ${money(Math.max(0,C.round(BI.amount(row)-now)))}. Wpłata została policzona raz.`;
 },null,'scroll-modal','Potwierdź wpłatę');
 for(const checkbox of $('#dialog').querySelectorAll('input[name="paidReceipt"]'))checkbox.onchange=()=>{const ids=new Set(new FormData($('#modal-form')).getAll('paidReceipt'));$('#f-paidAmount').value=Math.max(0,C.round(remaining-earlier.filter(r=>ids.has(r.id)).reduce((sum,r)=>sum+C.number(r.amount),0)));};
}
async function invoiceDialog(id){
 await loadStageInvoices();const row=(stageInvoiceCache.get(selected.id)||[]).find(r=>r.id===id);
 if(!row)throw Error('Nie znaleziono faktury. Odśwież listę.');
 const record=(p().invoiceSettlements||[]).find(r=>r.id===id),base=BI.withoutInvoice(p(),id),targets=BI.targets(base);
 const earlier=BI.availableReceipts(p(),id);
 const earlierSection=`<section class="invoice-allocation-section"><h3>Wcześniej zapisane zaliczki i wpłaty</h3><p class="muted">Zaznacz otrzymane już kwoty. Zostaną powiązane z fakturą bez dodawania kolejnej wpłaty. Ich daty i cel rozliczenia pozostają zgodne z wcześniejszym zapisem.</p>${earlier.map(r=>`<label class="inline-check"><input type="checkbox" name="existingReceipt" value="${esc(r.id)}" ${record?.existingReceipts?.some(x=>x.id===r.id)?'checked':''}> <span><strong>${money(r.amount)}</strong> · ${date(r.date)} · ${r.kind==='materials'?'Zaliczka na materiały':'Za prace'}${r.note?'<br>'+esc(r.note):''}</span></label>`).join('')||'<p class="muted">Brak dostępnych wcześniejszych wpłat.</p>'}</section>`;
 const allocationRows=targets.map((t,i)=>{const a=record?.allocations.find(a=>a.key===t.key);return {target:t,html:`<tr><td>${esc(t.kind==='purchase'?t.label.replace(/^Materiały: /,''):t.label)}</td><td class="num">${t.kind==='materials'?'—':money(t.remaining)}</td><td>${input('assign-'+i,'Przypisz',a?.amount||0,'number','min="0" step="0.01"')}</td><td>${input('received-'+i,'Wpłata',a?.paid||0,'number','min="0" step="0.01"')}</td></tr>`};});
 const allocationTable=rows=>table(['Należność','Pozostało','Kwota z faktury','Otrzymano'],rows.map(r=>r.html).join(''));
 const materials=allocationRows.filter(r=>r.target.kind==='purchase'),advances=allocationRows.filter(r=>r.target.kind==='materials'),stages=allocationRows.filter(r=>r.target.kind==='stage'),wholeWork=allocationRows.filter(r=>r.target.kind==='work');
 const sections=`<section class="invoice-allocation-section allocation-materials" aria-labelledby="allocation-materials-title"><div class="toolbar"><h3 id="allocation-materials-title">Materiały</h3><button type="button" id="invoice-materials">Przypisz pozostałe materiały</button></div>${allocationTable(materials)}<h4>Zaliczka na przyszłe zakupy</h4><p class="muted small">Wpływ na materiały bez wskazywania konkretnego zakupu. Zwiększa zaliczki tylko raz. Wcześniej zapisaną zaliczkę zaznacz powyżej zamiast wpisywać ją ponownie.</p>${allocationTable(advances)}</section><section class="invoice-allocation-section allocation-work" aria-labelledby="allocation-work-title"><h3 id="allocation-work-title">Robocizna</h3><p class="muted small">Rozliczenie etapów prac</p>${allocationTable(stages)}<div class="allocation-whole-work"><h4>Rozliczenie całości robocizny</h4><p class="muted small">Pozostała kwota za wszystkie prace — zamiast przypisania jej do poszczególnych etapów.</p>${allocationTable(wholeWork)}</div></section>`;
 modal('Rozliczenie faktury '+esc(row.number),`<p>Kwota faktury: <strong>${money(BI.amount(row))}</strong>. W kolumnie „Otrzymano” wpisz łączną kwotę dotychczasowej wpłaty na daną należność.</p>${input('invoiceDate','Data wpływu',record?.date||C.today(),'date','required')}<div class="actions"><button type="button" id="invoice-full-paid">Otrzymano całą przypisaną kwotę</button></div>${earlierSection}<p class="muted">Poniżej wpisujesz tylko dodatkowe kwoty z faktury, poza zaznaczonymi wcześniejszymi wpłatami.</p>${sections}<p class="muted">Kwota przypisana może obejmować kilka należności. Przy częściowej wpłacie wskaż, które z nich opłacono. Wyzerowanie kwot cofa wyłącznie rozliczenie tej faktury.</p>`,fd=>{
  const next=BI.apply(p(),row,targets.map((t,i)=>({key:t.key,amount:C.number(fd.get('assign-'+i)),paid:C.number(fd.get('received-'+i))})),fd.get('invoiceDate'),fd.getAll('existingReceipt'));
  selected.payload=next;markDirty();
 },null,'scroll-modal invoice-allocation-modal');
 $('#invoice-materials').onclick=()=>{const checked=new Set(new FormData($('#modal-form')).getAll('existingReceipt')),used=earlier.filter(r=>checked.has(r.id)).reduce((s,r)=>s+C.number(r.amount),0);let room=Math.max(0,BI.amount(row)-used-targets.reduce((s,t,i)=>s+(t.kind==='purchase'?0:C.number($('#f-assign-'+i).value)),0));targets.forEach((t,i)=>{if(t.kind==='purchase'){const value=Math.min(room,t.remaining);$('#f-assign-'+i).value=C.round(value);room=C.round(room-value);}});};
 $('#invoice-full-paid').onclick=()=>{targets.forEach((t,i)=>{$('#f-received-'+i).value=$('#f-assign-'+i).value;});};
}
function settleAllDialog(completedOnly=false){const remaining=Math.max(0,C.round((completedOnly?Completion.summary(p()).workCost:C.finalWorkAmount(p()))-C.totals(p()).paid));modal('Rozlicz w całości',`<p>Pozostało za wszystkie prace: <strong>${money(remaining)}</strong>. Kwota uwzględnia dotychczasowe wpłaty i rozliczone faktury.</p>${input('date','Data wpływu',C.today(),'date','required')}<p class="muted">Jeśli wpłata dotyczy faktury, zapisz ją w sekcji „Faktury”, aby nie naliczyć jej dwa razy.</p>`,fd=>{if(remaining<=0)throw Error('Prace są już rozliczone.');p().receipts.push({id:C.uid(),date:fd.get('date'),kind:'work',stageId:'',amount:remaining,note:'Rozliczenie całości prac'});markDirty();},null,'','Potwierdź otrzymanie wpłaty');}

function receiptActions(row){
 const manual=(row.parts||[row]).filter(r=>p().receipts.some(x=>x.id===r.id));
 const buttons=r=>`<div class="actions">${btn('receipt-edit','Edytuj','',`data-id="${esc(r.id)}"`)}${btn('receipt-delete','Usuń','danger',`data-id="${esc(r.id)}"`)}</div>`;
 if(!row.invoiceId&&!row.purchaseId)return buttons(row);
 const source=row.invoiceId?btn('invoice-allocate','Edytuj rozliczenie faktury','',`data-id="${esc(row.invoiceId)}"`):btn('purchase-edit','Edytuj zakup','',`data-id="${esc(row.purchaseId)}"`);
 return source+(manual.length?`<details><summary>Edytuj / usuń wpłaty (${manual.length})</summary>${manual.map(r=>`<p>${date(r.date)} · ${money(r.amount)}</p>${buttons(r)}`).join('')}</details>`:'');
}
function changeReceipt(id,replacement){
 try{return BI.changeReceipt(p(),id,replacement);}catch(error){
  if(error.code!=='RS_RECEIPT_LINKS')throw error;
  if(!confirm('Ta wpłata jest powiązana z zakupami lub fakturą. '+(replacement?'Zmiana':'Usunięcie')+' wymaga odłączenia jej rozliczeń. Kontynuować? Kwoty pozostałe do rozliczenia zostaną przeliczone.'))return null;
  return BI.changeReceipt(p(),id,replacement,{detach:true});
 }
}
async function removeReceipt(id){
 const receipt=p().receipts.find(r=>r.id===id);if(!receipt)throw Error('Nie znaleziono wpłaty. Odśwież inwestycję.');
 if(!confirm(`Usunąć wpłatę ${money(receipt.amount)} z dnia ${date(receipt.date)}? Saldo inwestycji zostanie przeliczone.`))return;
 const next=changeReceipt(id,null);if(!next)return;selected.payload=next;markDirty();await flushChanges({normalize:false});render();
}
function paymentsView(){const d=p(),t=C.totals(d),percent=d.stages.reduce((s,x)=>s+C.number(x.percent),0);return `<div class="toolbar settlement-toolbar"><h2>Rozliczenie inwestycji</h2>${btn('settlement-open','Rozlicz inwestycję','primary')}</div><div class="metrics">${metric('Wpłaty za prace',money(t.paid))}${metric('Wartość całego zlecenia',money(t.works.after))}${metric(t.workRemaining<0?'Zaliczka na dalsze prace':'Pozostało za wykonane prace',money(Math.abs(t.workRemaining)))}${metric('Rozliczenie z materiałami',money(t.remaining),'gold')}</div>${t.workCredit?card(`<h2>Uzgodniona obniżka rozliczenia</h2><p><strong>${money(t.workCredit)}</strong> — ${esc(d.workCreditNote||'Obniżka za prace')}</p><p class="muted">Obniżka zmniejsza kwotę pozostałą do rozliczenia. Nie jest wpłatą i nie zwiększa zarobków.</p>`):''}${percent!==100?'<div class="notice">Suma procentów etapów wynosi '+C.quantity(percent)+'%. Ustaw łącznie 100%.</div>':''}${card(`<div class="toolbar"><h2>Etapy</h2>${btn('stage-add','Dodaj etap')}</div>${table(['Etap','Udział','Planowana kwota','Wpłaty','Termin','Faktura',''],d.stages.map(s=>`<tr><td><strong>${esc(s.name)}</strong><p class="muted" style="margin:4px 0">${esc(s.description)}</p></td><td>${C.quantity(s.percent)}%</td><td class="num">${money(t.agreed*s.percent/100)}</td><td class="num">${money(stagePaid(d,s.id))}</td><td>${date(s.due)}</td><td>${stageInvoiceCell(s)}</td><td>${btn('stage-edit','Edytuj','',`data-id="${s.id}"`)}</td></tr>`).join('')+`<tr><td><strong>Rozlicz w całości</strong></td><td>100%</td><td class="num">${money(C.finalWorkAmount(d))}</td><td class="num">${money(t.paid)}</td><td>—</td><td><a class="button" href="/bill/?new=1&brand=robisie&source=${encodeURIComponent(selected.id)}" target="_blank" rel="noopener">Wystaw fakturę</a></td><td>${btn('settle-all','Rozlicz w całości')}</td></tr>`)}<p class="muted" style="margin-top:14px">Etapy są liczone od zaakceptowanej oferty. Zmiana zakresu prac do rozliczenia końcowego: ${money(t.change)}.</p>`)}${invoiceList()}${card(`<div class="toolbar"><h2>Wpłaty inwestora</h2>${btn('receipt-add','Dodaj wpłatę','primary')}</div>${table(['Data','Rodzaj','Etap','Kwota','Opis',''],C.receiptRows(d).map(r=>`<tr><td>${date(r.date)}</td><td>${esc(r.kindLabel)}</td><td>${esc(r.stageLabel)}</td><td class="num">${money(r.amount)}</td><td>${esc(r.note)}</td><td>${receiptActions(r)}</td></tr>`).join(''))}`)}`;}
const shopName=value=>String(value??'').trim().replace(/\s+/g,' ');
const shopKey=value=>shopName(value).toLocaleLowerCase('pl');
function purchaseShopFilters(){
 const groups=new Map();for(const item of p().purchases){const key=shopKey(item.shop);if(!groups.has(key))groups.set(key,{name:shopName(item.shop)||'Bez sklepu',count:0,amount:0,paid:0,remaining:0});const group=groups.get(key);group.count++;group.amount+=C.number(item.amount);const payment=C.purchasePayment(item);group.paid+=payment.paid;group.remaining+=payment.remaining;}
 if(shopFilter!==null&&!groups.has(shopFilter))shopFilter=null;
 const tile=(key,name,count,amount,paid,remaining)=>btn('purchase-shop',`<strong>${esc(name)}</strong><small>Zakupy: ${count}</small><span class="shop-filter-amount" aria-label="Łączna kwota zakupów">${money(amount)}</span><small>Opłacono: ${money(paid)} · Pozostało: ${money(remaining)}</small>`,`shop-filter${shopFilter===key?' active':''}`,`data-shop="${esc(key??'')}"${key===null?' data-all="true"':''} aria-pressed="${shopFilter===key}"`);
 return `<div class="shop-filters" role="group" aria-label="Filtruj zakupy według sklepu">${tile(null,'Wszystkie',p().purchases.length,[...groups.values()].reduce((sum,g)=>sum+g.amount,0),[...groups.values()].reduce((sum,g)=>sum+g.paid,0),[...groups.values()].reduce((sum,g)=>sum+g.remaining,0))}${[...groups].sort((a,b)=>a[1].name.localeCompare(b[1].name,'pl')).map(([key,g])=>tile(key,g.name,g.count,g.amount,g.paid,g.remaining)).join('')}</div>`;
}
const shoppingQty=value=>new Intl.NumberFormat('pl-PL',{maximumFractionDigits:6}).format(value);
let shoppingFilter='remaining',shoppingByShop=false;
function shoppingNotice(){const matches=Shopping.suggestions(p()),invalid=Shopping.totals(p()).invalid;return matches.length||invalid?`<section class="notice shopping-notice"><strong>Lista „Do kupienia”: ${matches.length?'propozycje powiązań z fakturami — '+new Set(matches.map(m=>m.item.id)).size+' pozycji.':''} ${invalid?'Powiązania do sprawdzenia: '+invalid+'.':''}</strong> ${btn('nav','Sprawdź powiązania','primary','data-view="shopping"')}</section>`:'';}
function shoppingView(){
 const data=p(),totals=Shopping.totals(data),allRows=Shopping.rows(data),rows=allRows.filter(x=>shoppingFilter==='all'||(shoppingFilter==='bought'?x.state==='bought':x.state!=='bought'||x.invalid)),matches=Shopping.suggestions(data),sources=Shopping.purchaseLines(data);
 const itemMarkup=item=>`<article class="shopping-item ${item.state==='bought'?'shopping-bought':''}"><div class="shopping-item-heading"><label class="shopping-check"><input type="checkbox" data-action="shopping-check" data-id="${esc(item.id)}" aria-label="Kupione: ${esc(item.name)}" ${item.state==='bought'?'checked':''} ${item.linked>=item.quantity?'disabled':''}><span><strong>${esc(item.name)}</strong><small>${esc(item.shop||'Sklep nieokreślony')}</small></span></label><span class="shopping-status">${item.state==='bought'?'Kupione':item.state==='partial'?'Częściowo kupione':'Do kupienia'}${item.linked>0?' · faktura powiązana':item.bought>0?' · bez powiązanej faktury':''}</span></div><div class="shopping-item-meta"><span>Potrzeba: <b>${shoppingQty(item.quantity)} ${esc(item.unit)}</b></span><span>Kupiono: <b>${shoppingQty(item.bought)} ${esc(item.unit)}</b></span><span>Pozostało: <b>${shoppingQty(item.remaining)} ${esc(item.unit)}</b></span><span>Zakup: <b>${esc(item.date||'—')}</b></span><span>Z faktur: <b>${item.amount==null?'—':money(item.amount)}</b></span></div>${item.invalid?'<p class="notice error">Powiązana faktura, ilość lub jednostka zmieniła się. Sprawdź powiązanie — nieprawidłowej części nie liczymy jako potwierdzonego zakupu.</p>':''}<div class="actions">${btn('shopping-edit','Edytuj','',`data-id="${esc(item.id)}"`)}${item.linked<item.quantity?btn('shopping-match','Powiąż z fakturą','',`data-id="${esc(item.id)}" ${sources.length?'':'disabled'}`):''}</div><details><summary>Szczegóły i dokumenty (${item.links.length})</summary><p>Wpisano na liście: ${esc(item.originalName||item.name)}</p>${item.links.map(link=>`<div class="shopping-link"><p>${esc(link.source?.name||'Pozycja niedostępna')} · ${shoppingQty(link.quantity)} ${esc(link.source?.unit||item.unit)} · ${link.amount==null?'Kwota do sprawdzenia':money(link.amount)}<br>${esc(link.source?.shop||'')} · ${esc(link.source?.date||'')} ${link.source?`<a href="/app/robisie/?project=${encodeURIComponent(selected.id)}&amp;purchaseKsef=${encodeURIComponent(link.source.ksef)}" data-action="purchase-edit" data-id="${esc(link.purchaseId)}">${esc(link.source.invoice||'Otwórz zakup')}</a>`:''}</p>${btn('shopping-unlink','Odłącz powiązanie','',`data-id="${esc(item.id)}" data-purchase="${esc(link.purchaseId)}" data-index="${link.index}"`)}</div>`).join('')||'<p>Zakup nie ma jeszcze powiązanej faktury.</p>'}</details></article>`;
 const groups=new Map();for(const row of rows){const key=shoppingByShop?row.shop||'Sklep nieokreślony':'';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(row);}
 return `<div class="shopping-page"><div class="metrics">${metric('Do kupienia',totals.needed)}${metric('Częściowo kupione',totals.partial)}${metric('Kupione',totals.bought)}${metric('Wartość powiązanych zakupów',money(totals.amount))}</div>${totals.unknown?'<p class="notice">Część powiązań nie ma jednoznacznej kwoty. Nie wliczamy ich do podanej wartości.</p>':''}${card(`<div class="toolbar"><h2>Do kupienia</h2><div class="actions">${btn('shopping-add','+ Dodaj pozycję','primary')}${btn('shopping-refresh','Odśwież faktury')}</div></div><p class="muted">Odhacz zakup w sklepie. Później powiąż go z fakturą — także gdy jest już odhaczony. Powiązanie uzupełnia dane zakupu i nie dodaje ponownie kosztu.</p><div class="row"><label>Widok<select id="shopping-filter"><option value="remaining" ${shoppingFilter==='remaining'?'selected':''}>Do kupienia / do sprawdzenia</option><option value="all" ${shoppingFilter==='all'?'selected':''}>Wszystkie</option><option value="bought" ${shoppingFilter==='bought'?'selected':''}>Kupione</option></select></label><label class="inline-check"><input type="checkbox" id="shopping-by-shop" ${shoppingByShop?'checked':''}> Grupuj według sklepu</label></div><div class="shopping-items">${[...groups].sort((a,b)=>a[0].localeCompare(b[0],'pl')).map(([name,items])=>`${name?`<h3>${esc(name)}</h3>`:''}${items.map(itemMarkup).join('')}`).join('')||'<p class="empty">Brak pozycji w tym widoku.</p>'}</div>`)}${card(`<h2>Propozycje powiązań z fakturami</h2><p class="muted">Porównujemy nazwę towaru, jednostkę i sklep. Każde powiązanie zatwierdzasz sam. Ilości pochodzą wyłącznie z zakupów przypisanych do tej inwestycji.</p>${matches.map(({item,line})=>`<div class="shopping-proposal"><div><strong>${esc(item.originalName||item.name)}</strong><small>Lista: ${esc(item.shop||'dowolny sklep')} · potrzeba ${shoppingQty(Math.max(0,item.quantity-item.linked))} ${esc(item.unit)}</small><p>↳ ${esc(line.name)} · ${esc(line.shop)}<br>${esc(line.invoice)} · ${esc(line.date)} · dostępne ${shoppingQty(Shopping.available(data,line))} ${esc(line.unit)} · ${line.amount==null?'kwota do sprawdzenia':money(line.amount)}</p></div>${btn('shopping-match','Sprawdź i powiąż','primary',`data-id="${esc(item.id)}" data-source="${esc(line.key)}"`)}</div>`).join('')||'<p>Brak nowych propozycji. Przy pozycji listy możesz sam wybrać „Powiąż z fakturą”.</p>'}${(data.purchases||[]).some(x=>x.ksefCorrections?.length)?'<p class="notice">Zakupy z korektami wymagają sprawdzenia dokumentów. Nie proponujemy ich automatycznie.</p>':''}<p class="muted">Jeśli przypisana faktura nie zawiera zapisanych pozycji, otwórz ją w „Zakupach i materiałach” i zapisz wybór towarów.</p>`)}</div>`;
}
function shoppingDialog(id){const old=(p().shoppingList||[]).find(x=>x.id===id);if(id&&!old)throw Error('Nie znaleziono pozycji.');modal(id?'Edytuj pozycję listy':'Dodaj do kupienia',`<div class="grid">${input('name','Co kupić',old?.name||'','text','required maxlength="300"')}${input('shop','Sklep (opcjonalnie)',old?.shop||'','text','list="shopping-shops" maxlength="300"')}<datalist id="shopping-shops">${shopSuggestions().map(s=>`<option value="${esc(s)}">`).join('')}</datalist>${input('quantity','Potrzebna ilość',old?.quantity??1,'number','required')}${input('unit','Jednostka (opcjonalnie)',old?.unit||'','text','placeholder="np. szt., m², l" maxlength="30"')}${input('boughtQuantity','Ręcznie oznaczona ilość kupiona',old?.boughtQuantity||0,'number')}${input('boughtDate','Data ręcznego zakupu',old?.boughtDate||C.today(),'date')}</div><p class="muted">Pozostaw ilość 1, jeśli nie potrzebujesz podziału. Ilości z faktury i ręczne odhaczenie opisują ten sam zakup — nie sumujemy ich podwójnie.</p>`,fd=>{selected.payload=Shopping.saveItem(p(),Object.fromEntries(fd),id);markDirty();},id?()=>{if((old.links||[]).length)throw Error('Najpierw odłącz powiązania z fakturami.');selected.payload=Shopping.remove(p(),id);markDirty();}:null);}
function shoppingMatchDialog(id,sourceKey){
 const item=Shopping.rows(p()).find(x=>x.id===id);if(!item)throw Error('Nie znaleziono pozycji.');
 const lines=Shopping.purchaseLines(p()).filter(line=>Shopping.available(p(),line)>0).sort((a,b)=>Shopping.score(item,b)-Shopping.score(item,a));if(!lines.length)throw Error('Brak dostępnych pozycji faktur w tej inwestycji.');
 const initial=lines.find(x=>x.key===sourceKey)||lines[0];let chosen=initial;
 modal('Powiąż zakup z listą',`<p>Lista: <strong>${esc(item.originalName||item.name)}</strong> · ${shoppingQty(item.quantity)} ${esc(item.unit)} · ${esc(item.shop||'dowolny sklep')}</p><label class="field">Pozycja przypisanej faktury<select name="sourceKey" id="shopping-source">${lines.map(line=>`<option value="${esc(line.key)}" ${line.key===initial.key?'selected':''}>${esc(line.name)} · ${esc(line.shop)} · ${esc(line.invoice)} · poz. ${line.index} · ${shoppingQty(Shopping.available(p(),line))} ${esc(line.unit)}</option>`).join('')}</select></label>${input('quantity','Ilość do powiązania (jednostka z faktury)',Math.min(item.quantity-item.linked,Shopping.available(p(),initial)),'number','required')}<div class="notice" id="shopping-match-preview"></div><p class="muted">Po zatwierdzeniu nazwa, sklep, data i kwota będą pobierane z tej pozycji. Dokument pozostaje jedynym źródłem kosztu. Różne jednostki wymagają poprawienia jednostki na liście — nie przeliczamy ich automatycznie.</p>`,fd=>{selected.payload=Shopping.link(p(),id,fd.get('sourceKey'),fd.get('quantity'));markDirty();},null,'scroll-modal','Zatwierdź powiązanie');
 const preview=()=>{const n=C.number($('#f-quantity').value),amount=chosen.amount==null?null:C.round(chosen.amount*n/chosen.quantity);$('#shopping-match-preview').textContent=`${chosen.name} · ${chosen.shop} · ${chosen.date||'brak daty'} · dostępne ${shoppingQty(Shopping.available(p(),chosen))} ${chosen.unit} · ${amount==null?'kwota do sprawdzenia':money(amount)}${item.unit&&Shopping.unit(item.unit)!==Shopping.unit(chosen.unit)?' · UWAGA: inna jednostka niż na liście':''}`;};
 $('#shopping-source').onchange=()=>{chosen=lines.find(x=>x.key===$('#shopping-source').value)||initial;$('#f-quantity').value=Math.min(item.quantity-item.linked,Shopping.available(p(),chosen));preview();};$('#f-quantity').addEventListener('input',preview);preview();
}

function purchasesView(){const t=C.purchaseTotals(p()),filters=purchaseShopFilters(),items=p().purchases.filter(x=>shopFilter===null||shopKey(x.shop)===shopFilter);return `${shoppingNotice()}<div class="metrics">${metric('Otrzymane zaliczki',money(t.advances))}${metric('Faktyczne wydatki',money(t.spent))}${metric('Koszt dla inwestora',money(t.charged))}${metric(t.balance>=0?'Do zwrotu inwestorowi':'Dopłata inwestora',money(Math.abs(t.balance)),'gold')}${metric('Różnica rozliczenia',money(t.difference))}</div>${card(`<div class="toolbar"><h2>Zakupy materiałów</h2><div class="actions">${btn('purchases-settle','Rozlicz zakupy','primary')}${btn('purchase-add','Dodaj zakup')}</div></div>${filters}<p class="muted purchase-filter-info" aria-live="polite">Pokazano ${items.length} z ${p().purchases.length} zakupów. Podsumowanie finansowe obejmuje całą inwestycję.</p>${table(['Data','Sklep','Zakup / dokument','Kwota zakupu','Koszt inwestora','Rozliczono z inwestorem',''],items.map(x=>`<tr class="${C.purchaseNeedsInvoice(x)?'purchase-needs-invoice':''}"><td>${date(x.date)}</td><td>${esc(x.shop)}</td><td>${C.purchaseNeedsInvoice(x)?'<span class="invoice-required">wymaga faktury</span><br>':''}${esc(x.description)}<br><span class="muted">${esc(x.invoice)}${x.sourceKsefNumber?'<br>KSeF: '+esc(x.sourceKsefNumber):''}${x.ksefCorrections?.map(c=>'<br>Korekta '+esc(c.number)+': '+money(c.amount)).join('')||''}</span></td><td class="num">${money(x.amount)}</td><td class="num">${money(x.charge)}</td><td class="purchase-status ${C.purchasePayment(x).state}">${esc(C.purchasePaymentLabel(x))}</td><td>${btn('purchase-edit','Edytuj','',`data-id="${x.id}"`)}</td></tr>`).join(''))}<p class="muted" style="margin-top:16px">Tutaj zapisujesz koszty materiałów, także z faktur zakupowych KSeF. Wpłaty inwestora i faktury sprzedażowe rozliczasz w „Etapach i płatnościach”. Ręcznie odnotowana przy zakupie wpłata inwestora zwiększa otrzymane zaliczki — nie dodawaj jej ponownie. Koszt inwestora można ustalić niezależnie od kwoty zakupu.</p>`)} `;}
function journalView(){return card(`<div class="toolbar"><h2>Wpisy dziennika</h2>${btn('journal-add','Dodaj wpis','primary')}</div>${p().journal.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<div class="history"><div class="toolbar"><strong>${date(x.date)} · ${esc(x.roomId?roomName(x.roomId):'Cała inwestycja')}</strong>${btn('journal-edit','Edytuj','',`data-id="${x.id}"`)}</div><p style="white-space:pre-wrap">${esc(x.description)}</p><p class="muted">Potwierdzenie inwestora: ${x.investorConfirmed?'tak':'brak'} · wykonawcy: ${x.contractorConfirmed?'tak':'brak'}</p></div>`).join('')||'<div class="empty">Brak wpisów w dzienniku.</div>'}`);}
function contractView(){const d=p();return card(`<div class="grid">${field('contractDate','Data umowy',d.contractDate,'date')}${field('contractPlace','Miejsce zawarcia umowy',d.contractPlace)}${field('paymentDays','Termin zapłaty faktury (dni)',d.paymentDays,'number','min="0"')}${field('materialAdvance','Uzgodniona zaliczka na materiały (zł)',d.materialAdvance,'number','min="0" step="0.01"')}${field('terminationPercent','Uzgodniona kara za rozwiązanie (%)',d.terminationPercent,'number','min="0" max="100"')}</div><div class="actions" style="margin-bottom:20px">${btn('contract-edit','Edytuj pełną treść umowy')}${btn('contract-generate','Wstaw treść z aktualnych danych')}</div><div class="contract-preview"><pre class="document">${esc(PDF.contractParts(d.contractText||C.contractTemplate(selected,config.payload)).text)}</pre><div class="contract-preview-signatures"><span>${esc(PDF.contractParts(d.contractText||C.contractTemplate(selected,config.payload)).contractor)}<br>Data i podpis Wykonawcy</span><span>${esc(PDF.contractParts(d.contractText||C.contractTemplate(selected,config.payload)).investor)}<br>Data i podpis Inwestora</span></div></div><p class="muted">Po edycji pełnej treści zmiany danych nie nadpisują jej automatycznie. „Wstaw treść z aktualnych danych” przygotowuje nowy tekst.</p>`);}
function handoverView(){const d=p(),h=d.handover,closed=d.status==='zakonczona',entry=projectEarningsCache.get(selected.id);return card(`<div class="grid">${input('handover.date','Data odbioru',h.date,'date','data-handover="date"')}${input('handover.receiver','Odbiorca (jeśli inny niż inwestor)',h.receiver,'text','data-handover="receiver"')}</div><label class="inline-check"><input type="checkbox" data-handover="accepted" ${h.accepted?'checked':''}> Prace zaakceptowane przez inwestora</label><div style="margin-top:16px">${text('handover.notes','Uwagi do wykonanych prac',h.notes,'data-handover="notes"')}</div><p class="muted">Dokument ${esc(C.attachment(selected,'PZO'))} zawiera dane inwestycji, zakres wykonanych prac i miejsce na podpisy.</p>${closed?`<p><span class="tag zakonczona">Zakończona</span> <span class="tag ${Completion.summary(d).open?'odbior':'prace'}">${Completion.status(d)}</span></p><p class="muted">${entry?'Wpis w Moich zarobkach: '+money(entry.my_amount)+'.':'Inwestycja nie została jeszcze dodana do Moich zarobków.'}</p><div class="actions">${btn('completion-review','Zobacz rozliczenie')}${btn('reopen','Cofnij zakończenie inwestycji')}${entry?'<a class="button primary" href="/pack/?module=finances" target="_top">Zobacz w moich zarobkach</a>':btn('earnings-add','Dodaj do moich zarobków','primary')}</div>`:`<p class="muted">Przed zakończeniem sprawdzisz rozliczenie materiałów i robocizny. Dodanie do zarobków jest osobnym krokiem.</p>${btn('finish','Zakończ','primary')}`}`);}
async function refreshCompletionData(){
 await flushChanges();const id=selected.id,revision=selected.revision;
 const [row,documents,earnings]=await Promise.all([API.project(id),API.stageInvoices(id),API.projectEarnings(id)]);
 if(selected?.id!==id||selected.revision!==revision||projectDirty||writes.pending)throw Error('Inwestycja zmieniła się. Otwórz rozliczenie ponownie.');
 if(!row)throw Error('Nie znaleziono inwestycji.');
 selected=structuredClone(row);all=all.map(item=>item.id===id?structuredClone(row):item);stageInvoiceCache.set(id,documents);projectEarningsCache.set(id,earnings||null);render();
}
async function loadProjectEarnings(){const id=selected?.id;if(!id||!API.projectEarnings)return;try{const entry=await API.projectEarnings(id);projectEarningsCache.set(id,entry||null);if(selected?.id===id&&view==='handover')render();}catch{if(selected?.id===id)toast('Nie udało się sprawdzić wpisu w zarobkach. Ponów otwarcie odbioru.');}}
function acceptCompletionRow(row){selected=structuredClone(row);all=all.map(item=>item.id===row.id?structuredClone(row):item);projectDirty=false;drafts.remove('project:'+row.id);saveError='';updateSaveState();}
async function completionDialog(){
 await refreshCompletionData();const baseline=structuredClone(selected),closed=p().status==='zakonczona',summary=Completion.summary(p());
 const handover=closed?'':`<div class="grid">${input('completionDate','Data odbioru',p().handover.date||C.today(),'date','required data-handover="date"')}<label class="inline-check"><input data-handover="accepted" name="completionAccepted" type="checkbox" ${p().handover.accepted?'checked':''} required> Prace zaakceptowane przez inwestora</label></div>`;
 modal(closed?'Rozliczenie zakończonej inwestycji':'Zamknięcie inwestycji',handover+Completion.markup({...p(),id:selected.id},stageInvoiceCache.get(selected.id)),async fd=>{
  if(closed)return;
  if(selected.id!==baseline.id||selected.revision!==baseline.revision)throw Error('Inwestycja zmieniła się. Otwórz zamknięcie ponownie.');
  if(!fd.get('completionDate')||!fd.has('completionAccepted'))throw Error('Uzupełnij datę odbioru i akceptację prac.');
  const warnings=[summary.due>0?'Do dopłaty: '+money(summary.due):'',summary.refund>0?'Do zwrotu: '+money(summary.refund):'',summary.unallocated>0?'Do przypisania do zakupów: '+money(summary.unallocated):'',summary.unfinished?'Prace nieoznaczone jako wykonane: '+summary.unfinished+' poz.':''].filter(Boolean);
  if(warnings.length&&!confirm(warnings.join('\n')+'\nZakończyć inwestycję z tym rozliczeniem?'))throw Error('Nie zakończono inwestycji. Możesz uzupełnić rozliczenia.');
  p().handover.date=fd.get('completionDate');p().handover.accepted=true;markDirty();await flushChanges({normalize:false});
  await writes.run(async()=>{const result=await API.finishProject(selected),row=Array.isArray(result)?result[0]:result;acceptCompletionRow(row);});
  toast('Zakończono inwestycję. Możesz teraz dodać ją do Moich zarobków.');
 },null,'scroll-modal completion-modal',closed?'Zamknij podsumowanie':'Zakończ inwestycję');
}
async function settlementDialog(){
 await refreshCompletionData();const summary=Completion.summary(p()),documents=stageInvoiceCache.get(selected.id)||[];
 const sales=documents.filter(row=>row.number&&row.status!=='draft'&&row.originKind!=='purchases'&&!row.payload?.correction&&!row.referenceOnly&&row.payload?.currency==='PLN');
 modal('Rozlicz inwestycję',`<p>Przejdź kolejno przez otrzymane pieniądze, zakupy i wykonaną robociznę. Samo wystawienie faktury nie potwierdza wpłaty.</p>
 <section class="settlement-step"><h3>1. Sprawdź wpływy z faktur</h3><p>Powiąż wcześniej zapisaną zaliczkę albo potwierdź nową wpłatę. Jedną wpłatę liczymy tylko raz.</p>${Completion.invoicesMarkup(p(),documents)}${sales.length?`<label class="field">Faktura<select id="settlement-invoice">${sales.map(r=>`<option value="${esc(r.id)}">${esc(r.number)}</option>`).join('')}</select></label><div class="actions">${btn('settlement-invoice-paid','Potwierdź wpływ')}${btn('settlement-invoice-link','Powiąż zaliczkę / podziel kwotę')}</div>`:'<p>Brak faktur sprzedażowych w PLN. Zapisane ręcznie zaliczki można wykorzystać w kolejnym kroku.</p>'}</section>
 <section class="settlement-step"><h3>2. Rozlicz zakupy materiałów</h3><p>Do zakupów można przypisać tylko faktycznie otrzymane środki. Przed zapisem zobaczysz podział na konkretne zakupy.</p><p><strong>Do przypisania do zakupów: ${money(summary.unallocated)}</strong> · saldo materiałów: ${money(summary.materialBalance)}.</p>${btn('settlement-purchases','Wybierz zaliczki i faktury','primary',summary.unallocated<=0?'disabled':'')}</section>
 <section class="settlement-step"><h3>3. Rozlicz wykonaną robociznę</h3><p>Wykonane prace: ${money(summary.workCost)} · otrzymano: ${money(summary.workReceived)} · ${summary.workBalance>0?'do zapłaty: '+money(summary.workBalance):'nie ma kwoty do dopłaty'}.</p>${btn('settlement-work','Potwierdź pozostałą wpłatę',summary.workBalance>0?'':'',summary.workBalance<=0?'disabled':'')}</section>
 <section class="settlement-step"><h3>Jednym potwierdzeniem</h3><p>Jeżeli otrzymano całą brakującą kwotę, najpierw wykorzystamy zapisane pieniądze, a każdą nową wpłatę pokażemy osobno do potwierdzenia.</p>${btn('settlement-all','Uregulowano całość','primary',summary.due<=0&&summary.unallocated<=0?'disabled':'')}</section>
 <p class="notice">Po każdej operacji wrócisz tutaj z aktualnymi kwotami. Zakończenie inwestycji i dodanie do zarobków pozostają osobnymi krokami.</p>`,()=>{},null,'scroll-modal completion-modal','Zamknij rozliczenie');
}
async function earningsDialog(){
 await refreshCompletionData();if(p().status!=='zakonczona')throw Error('Najpierw zakończ inwestycję.');
 const existing=projectEarningsCache.get(selected.id);if(existing){toast('Ta inwestycja jest już w Moich zarobkach.');return;}
 const baseline=structuredClone(selected),summary=Completion.summary(p()),amount=summary.workCost;
 modal('Dodaj do moich zarobków',`<p><strong>${esc(p().name)}</strong></p><p>Data odbioru: ${date(p().handover.date)}</p><div class="completion-total">${metric('Robocizna po rabatach i obniżkach',money(amount),'gold')}</div><p class="muted">Koszt materiałów ${money(summary.materialCost)} jest rozliczany osobno. Wpis dotyczy wartości wykonanej robocizny.</p>${summary.workBalance>0?'<p class="notice">Inwestor nie zapłacił jeszcze '+money(summary.workBalance)+' za robociznę. Dodanie zarobku nie zapisze wpłaty.</p>':''}`,async()=>{
  if(selected.id!==baseline.id||selected.revision!==baseline.revision)throw Error('Inwestycja zmieniła się. Otwórz dodawanie zarobku ponownie.');
  await writes.run(async()=>{const result=await API.addProjectEarnings(baseline,amount),entry=Array.isArray(result)?result[0]:result;projectEarningsCache.set(baseline.id,entry);});toast('Dodano inwestycję do Moich zarobków.');
 },null,'scroll-modal','Dodaj do moich zarobków');
}
async function settleAllCompletionDialog(){
 await refreshCompletionData();const baseline=structuredClone(selected),documents=stageInvoiceCache.get(selected.id)||[],preview=Completion.settleAll(baseline.payload,documents);
 const additions=table(['Źródło nowej wpłaty','Przeznaczenie','Kwota'],preview.additions.map(r=>`<tr><td>${esc(r.number)}</td><td>${r.kind==='materials'?'Materiały':'Wykonana robocizna'}</td><td class="num">${money(r.amount)}</td></tr>`).join(''));
 modal('Uregulowano całość',`<p>Rozliczymy zakupy i wykonaną robociznę, zachowując wcześniejsze wpłaty oraz ich powiązania.</p><div class="metrics">${metric('Zakupy rozliczane teraz',money(preview.allocated))}${metric('Nowa wpłata do potwierdzenia',money(preview.newMoney),'gold')}</div>${preview.newMoney>0?`${input('fullSettlementDate','Data otrzymania brakującej wpłaty',C.today(),'date','required')}${additions}<label class="inline-check"><input type="checkbox" name="confirmSettlementMoney" required> Potwierdzam otrzymanie dodatkowych ${money(preview.newMoney)} od inwestora.</label>`:'<p class="positive">Wystarczą wcześniej zapisane pieniądze. Nie dodamy nowej wpłaty.</p>'}${preview.after.refund>0?`<p class="notice">Pozostanie ${money(preview.after.refund)} do zwrotu inwestorowi. To rozliczenie nie potwierdza wykonania zwrotu.</p>`:''}${preview.before.unfinished?`<p class="notice">Pozycje nieoznaczone jako wykonane (${preview.before.unfinished}) pozostaną poza rozliczeniem robocizny.</p>`:''}<h3>Faktury po rozliczeniu</h3>${Completion.invoicesMarkup(preview.project,documents)}<p class="muted">Nowe wpłaty przypiszemy do niezapłaconej części faktur sprzedażowych, do wysokości brakującego rozliczenia. Resztę zapiszemy jako wpłatę bez faktury. To nie kończy inwestycji ani nie dodaje zarobku.</p>`,fd=>{
  if(selected.id!==baseline.id||selected.revision!==baseline.revision)throw Error('Inwestycja zmieniła się. Otwórz rozliczenie ponownie.');
  if(preview.newMoney>0&&!fd.has('confirmSettlementMoney'))throw Error('Potwierdź otrzymanie brakującej wpłaty.');
  const result=Completion.settleAll(baseline.payload,documents,preview.newMoney>0?fd.get('fullSettlementDate'):C.today());
  selected.payload=result.project;markDirty();
 },null,'scroll-modal completion-modal','Potwierdź rozliczenie');
}
const defaultUnits=['m²','mb','szt.','godz.','kpl','m','m³'];
const customUnitValue='__robisie_custom_unit__';
const cleanUnit=value=>String(value||'').trim().replace(/\s+/g,' ');
function unitOptions(current=''){const values=[...defaultUnits,...(config.payload.units||[]),...config.payload.catalog.map(x=>x.unit),...all.flatMap(x=>[...(x.payload.offer||[]),...(x.payload.works||[])].map(l=>l.unit)),current];const result=[],seen=new Set();for(const value of values){const unit=cleanUnit(value),key=unit.toLocaleLowerCase('pl');if(unit&&!seen.has(key)){seen.add(key);result.push(unit);}}return result;}
function unitField(current='',required=true){const options=unitOptions(current),value=options.find(x=>x.toLocaleLowerCase('pl')===cleanUnit(current).toLocaleLowerCase('pl'))||'';return `<div class="field"><label for="f-unit">Jednostka</label><select id="f-unit" name="unit" ${required?'required':''}><option value="">Wybierz jednostkę</option>${options.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('')}<option value="${customUnitValue}">Dodaj własną…</option></select></div><div id="custom-unit-field" hidden>${input('customUnit','Własna jednostka','','text','disabled maxlength="40"')}<p class="muted">Po zapisaniu będzie dostępna na liście przy kolejnych pracach.</p></div>`;}
function bindUnitField(){const select=$('#f-unit'),custom=$('#f-customUnit');select.onchange=()=>{const own=select.value===customUnitValue;$('#custom-unit-field').hidden=!own;custom.disabled=!own;custom.required=own;if(own)custom.focus();};}
function chooseServiceUnit(value){const select=$('#f-unit'),unit=cleanUnit(value),option=Array.from(select.options).find(x=>x.value.toLocaleLowerCase('pl')===unit.toLocaleLowerCase('pl'));select.value=option?option.value:unit?customUnitValue:'';$('#f-customUnit').value=option?'':unit;select.onchange();}
function readUnit(fd,required=true){const unit=cleanUnit(fd.get('unit')===customUnitValue?fd.get('customUnit'):fd.get('unit'));if(required&&!unit)throw new Error('Wybierz jednostkę lub dodaj własną.');if(unit.length>40||unit===customUnitValue)throw new Error('Jednostka może mieć najwyżej 40 znaków.');return unit;}
async function rememberUnit(unit){if(!unit||[...defaultUnits,...(configBaseline.payload.units||[])].some(x=>x.toLocaleLowerCase('pl')===unit.toLocaleLowerCase('pl')))return;const payload=structuredClone(configBaseline.payload);payload.units=[...(payload.units||[]),unit];await persistCatalog(payload);}
function serviceGroups(services){const groups=new Map();for(const service of services){const category=service.category||'Pozostałe prace';if(!groups.has(category))groups.set(category,[]);groups.get(category).push(service);}return [...groups];}
function serviceCategories(services,rows){return serviceGroups(services).map(([category,items])=>`<details class="service-category"><summary><span>${esc(category)}</span><small>${items.length} poz.</small></summary><div class="category-items">${rows(items)}</div></details>`).join('');}
function servicePicker(services){return `<fieldset class="service-picker"><legend>Usługa z cennika</legend><p class="muted">Rozwiń kategorię i wybierz konkretną pracę.</p>${serviceCategories(services,items=>items.map(x=>`<label class="service-option"><input type="radio" name="serviceId" value="${esc(x.id)}" required><span><strong>${esc(x.name)}</strong><small>${esc(x.unit||'Jednostka do ustalenia')}</small></span><span class="service-price">${money(x.base*(1+currentMarkup()/100))}</span></label>`).join(''))||'<p class="muted">Cennik jest pusty. Dodaj usługę w cenniku.</p>'}</fieldset>`;}
function catalogView(){const s=config.payload,services=currentCatalog(),markup=currentMarkup();return card(`<div class="grid">${input('markup',selected?'Podwyższenie ceny bazowej w tej inwestycji (%)':'Domyślne podwyższenie dla nowych inwestycji (%)',markup,'number',`${selected?'data-field':'data-config'}="markup" min="0" step="0.01"`)}</div><div class="toolbar"><p class="muted">${selected?'Podwyższenie jest niezależne dla tej inwestycji. Ceny zapisanych pozycji oferty i realizacji zachowują swoje wartości.':'Nowe inwestycje otrzymują aktualne ceny bazowe i powyższe podwyższenie. Roczna korekta zmienia bazę dla przyszłych inwestycji.'}</p><div class="actions">${btn('service-add','Dodaj usługę')}${!selected?btn('catalog-correct','Korekta cennika bazowego'):''}</div></div>${serviceCategories(services,items=>table(['Usługa','Jedn.','Cena bazowa','Cena po podwyższeniu',''],items.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.unit||'do ustalenia')}</td><td class="num">${money(x.base)}</td><td class="num">${money(x.base*(1+markup/100))}</td><td><div class="actions">${btn('service-edit','Edytuj','',`data-id="${esc(x.id)}"`)}${!selected?btn('service-delete','Usuń','danger',`data-id="${esc(x.id)}"`):''}</div></td></tr>`).join('')))}<p class="muted" style="margin-top:16px">Usługi dodawane tutaj lub podczas dodawania pracy są zapisywane we wspólnym katalogu i dostępne we wszystkich inwestycjach.</p>${!selected?catalogHistory():''}`);}
function catalogHistory(){const history=config.payload.catalogCorrections||[];if(!history.length)return '';return `<details class="import-history"><summary>Historia korekt cennika (${history.length})</summary>${table(['Data','Korekta','Powód','Status'],[...history].reverse().map(item=>`<tr><td>${esc(new Date(item.date).toLocaleString('pl-PL',{timeZone:'Europe/Warsaw'}))}</td><td>${item.percent>0?'+':''}${esc(item.percent)}%</td><td>${esc(item.reason||'—')}</td><td>${item.undoneAt?'Cofnięta':'Zastosowana'}</td></tr>`).join(''))}${C.lastCatalogCorrection(config.payload)?btn('catalog-undo','Cofnij ostatnią korektę'):''}</details>`;}
function catalogCorrectionDialog(){if(dirty){toast('Poczekaj na automatyczny zapis ustawień.');return;}const original=structuredClone(config.payload);modal('Korekta cennika bazowego',`<div class="grid">${input('percent','Korekta (%)','','number','step="0.01" min="-99.99" max="1000" required')}${input('reason','Powód (opcjonalnie)','','text','maxlength="200"')}</div><p class="muted">Dodatni procent podnosi ceny, ujemny obniża. Korekta trwale zmieni ceny bazowe. Istniejące inwestycje, oferty i rozliczenia zachowają swoje ceny. Podwyższenie dla nowych inwestycji pozostanie bez zmian.</p><div id="correction-preview" aria-live="polite"><p>Wpisz procent, aby zobaczyć nowe ceny.</p></div>`,async fd=>{const next=C.correctCatalog(original,fd.get('percent'),fd.get('reason'));await persistCatalog(next);dirty=false;toast('Zapisano korektę całego cennika bazowego.');},null,'correction-modal','Zastosuj do całego cennika');$('#f-percent').oninput=()=>{try{const changes=C.catalogCorrectionPreview(original.catalog,C.calculateNumber($('#f-percent').value));$('#correction-preview').innerHTML=table(['Kategoria / usługa','Obecna cena bazowa','Nowa cena bazowa'],changes.map(item=>`<tr><td><small>${esc(item.category)}</small><br>${esc(item.name)}</td><td class="num">${money(item.before)}</td><td class="num">${money(item.after)}</td></tr>`).join(''));}catch(error){$('#correction-preview').innerHTML=`<p class="muted">${esc(error.message)}</p>`;}};}
async function undoCatalog(){if(dirty){toast('Poczekaj na automatyczny zapis ustawień.');return;}const last=C.lastCatalogCorrection(config.payload);if(!last)return;if(!confirm(`Cofnąć ostatnią korektę (${last.percent}%)? Ceny bazowe wrócą do poprzednich wartości. Istniejące inwestycje zachowają swoje ceny.`))return;await persistCatalog(C.undoCatalogCorrection(config.payload));render();toast('Cofnięto ostatnią korektę cennika.');}
function settingsView(){const c=config.payload.company;return card(`<div class="grid">${Object.entries({name:'Nazwa wykonawcy',address:'Adres',nip:'NIP',krs:'KRS',representative:'Osoba reprezentująca',account:'Numer rachunku'}).map(([k,v])=>input(k,v,c[k]||'','text',`data-company="${k}"`)).join('')}</div><p class="muted">Dane wykonawcy trafiają do generowanych dokumentów. Uzupełnij KRS i rachunek przed przygotowaniem umowy.</p>`);}
let modalScrollState=null;
function lockBackgroundScroll(){if(modalScrollState)return;const body=document.body.style,html=document.documentElement.style;modalScrollState={y:window.scrollY,position:body.position,top:body.top,width:body.width,overflow:body.overflow,htmlOverflow:html.overflow};body.position='fixed';body.top=`-${modalScrollState.y}px`;body.width='100%';body.overflow='hidden';html.overflow='hidden';}
function unlockBackgroundScroll(){if(!modalScrollState)return;const saved=modalScrollState;modalScrollState=null;const body=document.body.style;for(const key of ['position','top','width','overflow'])body[key]=saved[key];document.documentElement.style.overflow=saved.htmlOverflow;window.scrollTo(0,saved.y);}
function closeModal(){$('#dialog').close();unlockBackgroundScroll();}
const isNumericInput=el=>el?.dataset?.numeric==='true'||el?.type==='number';
function numericInputValue(el){
 const raw=String(el.value??'').trim();if(!raw){if(el.required)throw new Error('Wpisz liczbę lub działanie.');return 0;}
 const value=C.calculateNumber(raw);
 const min=el.getAttribute('min'),max=el.getAttribute('max');
 if(min!==null&&min!==''&&value<C.number(min))throw new Error(`Wynik musi wynosić co najmniej ${min}.`);
 if(max!==null&&max!==''&&value>C.number(max))throw new Error(`Wynik nie może przekraczać ${max}.`);
 return value;
}
function writeNumericValue(el,value){let target,key,scope='project';if(el.dataset.field){target=p();key=el.dataset.field;}else if(el.dataset.config){target=config.payload;key=el.dataset.config;scope='settings';}else if(el.dataset.line){target=p()[el.dataset.kind].find(line=>line.id===el.dataset.line);key=el.dataset.prop;}if(target&&target[key]!==value){target[key]=value;markDirty(scope);}}
